export const OPPORTUNITY_MAP_TEMPLATE = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Mindy Map</title>\n<link rel=\"icon\" type=\"image/png\" href=\"/brand/mindy-logo-icon.png\"/>\n<link rel=\"apple-touch-icon\" href=\"/brand/mindy-logo-icon.png\"/>\n<link rel=\"stylesheet\" href=\"https://unpkg.com/leaflet@1.9.4/dist/leaflet.css\"/>\n<style>\n  @import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@500;600;700&family=Inter:wght@400;500;600;700&family=IBM+Plex+Mono:wght@500;600&display=swap');\n  :root{\n    --ink:#111c26; --sub:#6b7787; --faint:#9aa5b3;\n    --line:#e6eaef; --hair:#f0f3f7; --bg:#fff; --wash:#f7f9fb;\n    --jan:#3b82f6; --grnd:#22a06b; --fac:#8b5cf6; --maint:#f59e0b;\n    --con:#ef4444; --ae:#0ea5e9; --it:#14b8a6; --sec:#64748b;\n    --train:#a855f7; --health:#ec4899; --heavy:#78716c; --dla:#0284c7;\n    --paint:#e11d48; --pest:#84cc16; --fence:#0891b2; --demo:#b45309;\n    --sam:#137a4e; --recomp:#b45309; --forecast:#7c3aed; --dlac:#0369a1; --sbir:#7c3aed; --grantc:#047857;\n    --hot:#d92d20; --warm:#b54708; --cool:#175cd3;\n    --score:#0f2233; --gold:#f5b400; --pos:#12805c; --fire:#ff7a45;\n    --disp:\"Space Grotesk\",system-ui,sans-serif; --ui:\"Inter\",system-ui,sans-serif;\n    --mono:\"IBM Plex Mono\",ui-monospace,monospace;\n    --sh1:0 1px 2px rgba(16,24,40,.06),0 1px 3px rgba(16,24,40,.1);\n    --sh2:0 4px 8px -2px rgba(16,24,40,.1),0 2px 4px -2px rgba(16,24,40,.06);\n    --sh3:0 12px 16px -4px rgba(16,24,40,.08),0 4px 6px -2px rgba(16,24,40,.03);\n  }\n  *{box-sizing:border-box;margin:0;padding:0}\n  html,body{height:100%;min-height:100%}\n  body{font-family:var(--ui);color:var(--ink);background:var(--bg);overflow:hidden;\n    -webkit-font-smoothing:antialiased}\n  button{font-family:inherit}\n  .app{display:grid;grid-template-columns:392px minmax(0,1fr);\n    grid-template-rows:minmax(0,1fr);\n    height:100vh;height:100dvh;min-height:560px;overflow:hidden;\n    transition:grid-template-columns .26s cubic-bezier(.4,0,.2,1)}\n  .app.collapsed{grid-template-columns:0px minmax(0,1fr)}\n  .app.collapsed .panel{opacity:0;pointer-events:none}\n  .panel{transition:opacity .18s}\n  /* sidebar collapse handle — sits above the map, outside Leaflet's panes */\n  .railbtn{position:fixed;top:50%;transform:translateY(-50%);z-index:1200;\n    left:392px;width:28px;height:56px;border:1px solid var(--line);border-left:none;\n    border-radius:0 10px 10px 0;background:#fff;color:var(--ink);cursor:pointer;\n    font-size:18px;line-height:1;box-shadow:var(--sh2);display:grid;place-items:center;\n    padding:0;transition:left .26s cubic-bezier(.4,0,.2,1),background .13s}\n  .railbtn:hover{background:var(--wash)}\n  .app.collapsed ~ .railbtn,.railbtn.collapsed{left:0}\n\n  /* ============ LEFT PANEL ============ */\n  .panel{display:flex;flex-direction:column;border-right:1px solid var(--line);min-width:0;background:#fff}\n\n  /* header */\n  .phead{padding:16px 20px 0;flex:none}\n  .brandrow{display:flex;align-items:baseline;justify-content:space-between;gap:10px}\n  .brand{font-family:var(--disp);font-weight:700;font-size:19px;letter-spacing:-.35px}\n  .badge-sd{font-family:var(--mono);font-size:9.5px;font-weight:600;letter-spacing:.1em;\n    color:var(--sam);background:#e7f4ee;border:1px solid #bfe3d3;padding:3px 7px;border-radius:5px}\n  .sumline{font-size:13px;color:var(--sub);margin-top:5px}\n  .sumline b{color:var(--ink);font-weight:600}\n\n  /* filter bar (sticky, Airbnb-style pills) */\n  .fbar{padding:12px 20px 10px;flex:none;border-bottom:1px solid var(--line);background:#fff}\n  .fscroll{display:flex;gap:7px;overflow-x:auto;padding-bottom:2px;scrollbar-width:none}\n  .fscroll::-webkit-scrollbar{display:none}\n  .fbtn{flex:none;display:inline-flex;align-items:center;gap:6px;font-size:12.5px;font-weight:500;\n    color:var(--ink);background:#fff;border:1px solid #d5dbe3;border-radius:999px;padding:7px 13px;\n    cursor:pointer;transition:.13s;white-space:nowrap}\n  .fbtn:hover{border-color:var(--ink);box-shadow:var(--sh1)}\n  .fbtn.active{background:var(--ink);border-color:var(--ink);color:#fff}\n  .fbtn .cnt{font-family:var(--mono);font-size:10.5px;opacity:.65}\n  .fbtn .car{font-size:9px;opacity:.5;transition:.2s}\n  .fbtn.open .car{transform:rotate(180deg)}\n  .clr{flex:none;font-size:12.5px;font-weight:500;color:var(--sub);background:none;border:none;\n    text-decoration:underline;cursor:pointer;padding:7px 4px;white-space:nowrap}\n  .clr:hover{color:var(--ink)}\n\n  /* dropdown sheet */\n  .sheet{display:none;padding:12px 0 4px;border-top:1px solid var(--hair);margin-top:11px}\n  .sheet.show{display:block}\n  .sheet h5{font-size:11px;font-weight:600;letter-spacing:.07em;text-transform:uppercase;\n    color:var(--faint);margin:0 0 9px}\n  .optgrid{display:grid;grid-template-columns:1fr 1fr;gap:2px 10px}\n  .opt{display:flex;align-items:center;gap:9px;padding:6px 4px;border-radius:7px;cursor:pointer;\n    font-size:13px;transition:.1s;user-select:none}\n  .opt:hover{background:var(--wash)}\n  .cbx{width:16px;height:16px;border-radius:4px;border:1.5px solid #cbd3dc;flex:none;\n    display:grid;place-items:center;transition:.12s;background:#fff}\n  .opt.on .cbx{background:var(--ink);border-color:var(--ink)}\n  .cbx svg{width:10px;height:10px;stroke:#fff;stroke-width:3;fill:none;opacity:0;transition:.1s}\n  .opt.on .cbx svg{opacity:1}\n  .opt .swatch{width:8px;height:8px;border-radius:50%;flex:none}\n  .opt .lbl{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n  .opt .n{font-family:var(--mono);font-size:11px;color:var(--faint)}\n  .sheetfoot{display:flex;gap:8px;padding:10px 0 2px;border-top:1px solid var(--hair);margin-top:8px}\n  .sfb{flex:1;font-size:12.5px;font-weight:600;padding:8px;border-radius:8px;cursor:pointer;border:1px solid var(--line);background:#fff;color:var(--ink)}\n  .sfb.pri{background:var(--ink);color:#fff;border-color:var(--ink)}\n\n  /* sort row */\n  .sortrow{display:flex;align-items:center;justify-content:space-between;gap:10px;\n    padding:10px 20px;flex:none;border-bottom:1px solid var(--line)}\n  .rescount{font-size:13px;font-weight:600}\n  .rescount span{font-weight:400;color:var(--sub)}\n  .sortsel{font-family:var(--ui);font-size:12.5px;font-weight:500;color:var(--ink);border:1px solid #d5dbe3;\n    border-radius:8px;padding:6px 26px 6px 10px;cursor:pointer;background:#fff url(\"data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 12 12'><path d='M3 4.5L6 8l3-3.5' stroke='%236b7787' stroke-width='1.5' fill='none' stroke-linecap='round'/></svg>\") no-repeat right 8px center;\n    -webkit-appearance:none;appearance:none}\n\n  /* ============ LISTING CARDS ============ */\n  .feed{flex:1;overflow-y:auto;padding:12px 16px 28px;scroll-behavior:smooth}\n  .card{background:#fff;border:1px solid var(--line);border-radius:14px;overflow:hidden;\n    margin-bottom:12px;cursor:pointer;transition:box-shadow .16s,border-color .16s,transform .16s}\n  .card:hover,.card.hot-hover{box-shadow:var(--sh3);border-color:#cfd7e0;transform:translateY(-1px)}\n  .card.sel{border-color:var(--ink);box-shadow:0 0 0 2px rgba(17,28,38,.09),var(--sh2)}\n\n  /* accent strip = category */\n  .cstrip{height:3px;width:100%}\n\n  .cbody{padding:13px 15px 14px}\n  /* DECISION-CARD hero — the estimate leads, like a Zillow price (Eric 2026-08-03). The number is the\n     biggest thing on the card; badges + title sit under it. Open/forecast = green M-Estimate tint;\n     recompete = amber (real contract value); pending = neutral. */\n  /* Estimate box a touch SHORTER (vertical padding 8->6.5px, ~15%) so the TITLE gains authority — the\n     opportunity title is what you're deciding on, not the value (Eric 2026-08-04). Font unchanged. */\n  .chero{border:1px solid var(--grnd-line,#cfe9d9);border-radius:11px;padding:6.5px 13px;margin-bottom:11px;\n    background:linear-gradient(150deg,#eef8f1,#f6fbf8)}\n  .chero.recomp{border-color:#f0d9b5;background:linear-gradient(150deg,#fffaf2,#fff7ee)}\n  /* forecast hero = violet tint (the agency's real published range, no ≈) — sibling to recompete's amber */\n  .chero.fore{border-color:#e4dcff;background:linear-gradient(150deg,#f6f2ff,#faf8ff)}\n  .chero.fore .cval{color:var(--forecast,#7c5cff)}\n  .chero.pending{border-color:var(--hair);background:linear-gradient(150deg,#f5f7fa,#fafbfc)}\n  /* Estimate leads, but must not out-shout the title (Eric 2026-08-04): hero ~18% shorter,\n     value 29→25px so the eye reads identity → number → title, not number first. */\n  .chero .cval{font-family:var(--disp);font-weight:800;font-size:25px;letter-spacing:-.7px;color:var(--ink);\n    line-height:1;font-variant-numeric:tabular-nums}\n  /* the ≈ glyph: SMALLER + almost faint (Eric 2026-08-05: \"the symbol smaller not the number\") — the\n     $ figure stays 25px/800; only the approx mark shrinks and fades so it reads as a quiet modifier. */\n  .chero .cval .apx{font-size:12px;color:var(--faint);opacity:.55;font-weight:600;vertical-align:2px;margin-right:1px}\n  .chero .cval.pend{font-size:17px;font-weight:700;color:var(--faint);letter-spacing:-.2px}\n  /* the tiny confidence line INSIDE the green box, under the ≈ estimate (Eric 2026-08-05) — very\n     small + faint, its own quiet tier beneath the big value. */\n  .chero .cconf{font-family:var(--sans);font-size:10.5px;font-weight:500;color:var(--faint);\n    letter-spacing:.01em;margin-top:3px;line-height:1.2}\n  /* row 1: source chip + deadline pill */\n  .crow1{display:flex;align-items:center;gap:7px;margin-bottom:9px;flex-wrap:wrap}\n  .chip{font-family:var(--mono);font-size:9.5px;font-weight:600;letter-spacing:.07em;\n    padding:3px 7px;border-radius:5px;text-transform:uppercase}\n  .chip.SAM{background:#e7f4ee;color:var(--sam)}\n  .chip.RECOMPETE{background:#fdf1e3;color:var(--recomp)}\n  .chip.DLA{background:#e4f1fb;color:var(--dlac)}\n  .chip.SBIR{background:#f0ebfd;color:var(--sbir)}\n  .chip.GRANTS{background:#dcfce7;color:var(--grantc)}\n  /* Company/contractor chip — soft purple tint, SAME family as the Open/Recompete chips above\n     (Eric 2026-07-28: the company card read heavier/flatter because its lead chip was a SOLID\n     strip-colored label while every other card's lead chip is a soft tinted pill). */\n  .chip.CO{background:#f0ebfd;color:#7c3aed}\n  /* Set-aside chip on a company card — light blue tint, distinct from the purple CO chip so an\n     8(a)/SDVOSB/WOSB firm's eligibility reads at a glance without another solid badge. */\n  .chip.sa{background:#eef4ff;color:var(--cool)}\n  /* Gov-buyer role chips (Eric 2026-07-28 card-parity): the person's real contact_title leads the\n     card. Contracting AUTHORITY (KO / Contracting Officer) gets the red decision-maker tint so the\n     person who can actually award pops; every other role gets the neutral blue role chip. */\n  .chip.ko{background:#fdecec;color:var(--hot)}\n  .chip.role{background:#eef4ff;color:var(--cool)}\n  .chip.docs{background:#eef0f3;color:var(--sub)}\n  /* Early-signal: this office posts sources-sought/presolicitation, i.e. you can\n     still shape the requirement. Green = go build the relationship. */\n  .chip.early.high{background:#dcfae6;color:#12805c}\n  .chip.early.medium{background:#eef7f3;color:#3f7a66}\n  .dl{display:inline-flex;align-items:center;gap:4px;font-size:11.5px;font-weight:600;\n    padding:3px 8px;border-radius:999px;margin-left:auto}\n  .dl.hot{background:#fef3f2;color:var(--hot)}\n  .dl.warm{background:#fffaeb;color:var(--warm)}\n  .dl.cool{background:#eff8ff;color:var(--cool)}\n  /* Company signal pill (right-aligned, dot). \"Active vendor\" — grounded: every firm on the\n     Companies map provably holds real federal awards, so the presence dot is true, not decorative.\n     Gives the company card the same right-aligned signal the Open (Due today) / Recompete\n     (Expiring soon) cards carry. (Eric 2026-07-28 card-parity pass.) */\n  .dl.co{background:#f0ebfd;color:#7c3aed}\n  .dl.dead{background:#f2f4f7;color:var(--faint)}\n  .dl i{width:5px;height:5px;border-radius:50%;background:currentColor;display:block}\n\n  /* title */\n  .ctitle{font-family:var(--disp);font-weight:700;font-size:15.5px;line-height:1.32;\n    letter-spacing:-.2px;margin-bottom:7px;\n    display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}\n\n  /* agency + location line */\n  .cmeta{display:flex;align-items:center;gap:6px;font-size:13px;color:var(--sub);margin-bottom:11px}\n  /* .ag holds the longest string on the line (a full department name), so it must be the part\n     that SHRINKS. Without min-width:0 a flex item refuses to shrink below its content, so the\n     agency stayed whole and crushed the location instead (\"LEAVENWORTH,…\" next to an untruncated\n     \"Department of Veterans Affairs\"). Shrink the agency; leave the short \"City, ST\" intact. */\n  .cmeta .ag{font-weight:600;color:var(--ink);flex:1 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n  .cmeta .ind{font-weight:600;color:var(--recomp);text-transform:uppercase;letter-spacing:.3px;font-size:11px}\n  .cmeta .dot{width:3px;height:3px;border-radius:50%;background:#cbd3dc;flex:none}\n  .cmeta .loc{flex:0 0 auto;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n  .cmeta .loc.noloc{color:var(--faint);font-style:italic}\n\n  /* the value strip — Zillow-style stat row */\n  .stats{display:flex;align-items:stretch;gap:0;background:var(--wash);border:1px solid var(--hair);\n    border-radius:10px;overflow:hidden;margin-bottom:11px}\n  .st{flex:1;padding:8px 10px;min-width:0}\n  .st + .st{border-left:1px solid #e8edf2}\n  .st .k{font-family:var(--mono);font-size:9px;letter-spacing:.09em;text-transform:uppercase;\n    color:var(--faint);margin-bottom:3px}\n  .st .v{font-size:13px;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n  /* A lone cell owns the full card width, so a long value (an office like \"National Oceanic and\n     Atmospheric Administration\") should WRAP rather than ellipsis away the part that identifies\n     it. Multi-cell rows keep the single-line strip — that's what makes them scannable. */\n  .st:only-child .v{white-space:normal;overflow:visible;text-overflow:clip}\n  .st .v.sd{color:var(--sam)}\n  .st .v.money{font-family:var(--disp);font-size:15px}\n  .st .v.hi{color:var(--pos)} .st .v.med{color:var(--warm)}\n\n  /* ---------- Opportunity DNA (Eric 2026-08-03, tasks/EPIC-opportunity-dna.md) ----------\n     Two languages, never crossed: IDENTITY = typography (agency = a brand, the WORD carries it,\n     one calm Landmark anchor) · BEHAVIOR = lucide icons (reserved for signals, never agencies).\n     NO emoji (de-vibe rule). Lifecycle = the category header, not a badge. */\n  .lchdr{display:flex;align-items:center;gap:8px;padding:9px 15px;border-bottom:1px solid var(--hair);\n    font-family:var(--sans);font-weight:800;font-size:10.5px;letter-spacing:.1em;text-transform:uppercase}\n  .lchdr .lcdot{width:6px;height:6px;border-radius:50%;flex:none}\n  .lchdr.open{color:var(--grnd,#0f9d58)} .lchdr.open .lcdot{background:var(--grnd,#0f9d58)}\n  .lchdr.recomp{color:var(--recomp,#b26a00)} .lchdr.recomp .lcdot{background:var(--recomp,#b26a00)}\n  .lchdr.fore{color:var(--forecast,#7c5cff)} .lchdr.fore .lcdot{background:var(--forecast,#7c5cff)}\n  .lchdr .lcwhen{margin-left:auto;font-weight:600;font-size:10.5px;letter-spacing:.01em;text-transform:none;color:var(--faint)}\n  /* urgency on the header's right (Eric 2026-08-04: \"OPEN NOW … 3 DAYS LEFT\"). soon = amber, ≤3d = red;\n     both uppercase + a leading dot so it reads as a status flag, not a date. */\n  .lchdr .lcwhen.soon{color:var(--warm,#b54708);font-weight:700;letter-spacing:.05em;display:inline-flex;align-items:center;gap:5px}\n  .lchdr .lcwhen.urg{color:var(--con,#d92d20);font-weight:700;letter-spacing:.05em;display:inline-flex;align-items:center;gap:5px}\n  .lchdr .lcwhen.soon::before,.lchdr .lcwhen.urg::before{content:\"\";width:5px;height:5px;border-radius:50%;background:currentColor}\n  /* Popup lifecycle header (Eric 2026-08-04, \"make it the strongest visual — very Apple\"): the\n     horizon drops to its OWN quiet line under the label instead of riding the far right, so the\n     header reads \"● OPEN NOW / 3 days left\". Popup-scoped so the compact result-list card header\n     (same .lchdr) keeps its single-strip rhythm. */\n  .pv .lchdr{flex-wrap:wrap}\n  .pv .lchdr .lcwhen{margin-left:0;flex-basis:100%;padding-left:14px;margin-top:2px;font-size:11px}\n  /* identity line: agency typography + one behavior icon */\n  .idrow{display:flex;align-items:center;gap:9px;flex-wrap:wrap;margin-bottom:10px}\n  .agid{display:inline-flex;align-items:center;gap:6px;font-family:var(--sans);font-weight:800;\n    font-size:12.5px;letter-spacing:.04em;text-transform:uppercase;color:var(--ink)}\n  .agid .dnaic{width:13px;height:13px;color:var(--faint);flex:none}\n  .beh{display:inline-flex;align-items:center;gap:5px;font-family:var(--sans);font-weight:700;font-size:11px;\n    padding:4px 8px 4px 6px;border-radius:7px;white-space:nowrap}\n  .beh .dnaic{width:12px;height:12px;flex:none}\n  .beh.sbf{background:var(--grnd-bg,#ecf8f1);color:var(--grnd-deep,#137a4e);border:1px solid var(--grnd-line,#cfe9d9)}\n  /* STORY beside the identity (\"Army · Repeat Buyer\") — same uppercase family as the agency but a\n     calmer weight/color so the identity reads FIRST and the behavioral story trails as context. */\n  .story{display:inline-flex;align-items:center;gap:6px;font-family:var(--sans);font-weight:700;\n    font-size:11.5px;letter-spacing:.03em;text-transform:uppercase;color:var(--grnd-deep,#137a4e)}\n  .story .middot{color:var(--faint);font-weight:600}\n  svg.dnaic{stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round;fill:none}\n  /* fit chips — the approved card artifact: green \"check\" chips below the buyer line, only when true */\n  /* \"Why this opportunity\" — a quiet section label above the popup's dedup'd chip row (Eric 2026-08-04). */\n  .whyhdr{font-family:var(--sans);font-weight:700;font-size:10.5px;letter-spacing:.07em;text-transform:uppercase;\n    color:var(--faint);margin:2px 0 8px}\n  /* the grounded confidence line under the ≈ estimate (Eric 2026-08-04) — tiny, quiet, not a score */\n  /* the grounded confidence line under the ≈ estimate — on BOTH the popup (.pv) and the list card\n     (.cbody). Tiny, quiet, not a score (Eric 2026-08-04/05). */\n  .pv .conf,.cbody .conf{font-family:var(--sans);font-size:11px;font-weight:500;color:var(--faint);margin:0 0 11px 2px;letter-spacing:.01em}\n  /* \"Why this opportunity\" GROUPED by meaning (Opportunity · Eligibility · Timing), pills WITHOUT\n     checkmarks (Eric 2026-08-04: reduce visual noise). Each group = a micro-label + a pill row. */\n  .wgrp{margin-bottom:10px}\n  .wglabel{font-family:var(--sans);font-weight:700;font-size:9.5px;letter-spacing:.09em;text-transform:uppercase;color:var(--faint);margin-bottom:6px}\n  .wprow{display:flex;flex-wrap:wrap;gap:7px}\n  .wpill{display:inline-flex;align-items:center;gap:5px;font-family:var(--sans);font-weight:600;font-size:12px;white-space:nowrap;\n    padding:5px 11px;border-radius:8px;background:var(--grnd-bg,#ecf8f1);color:var(--grnd-deep,#137a4e);border:1px solid var(--grnd-line,#cfe9d9)}\n  .wpill.elig{background:#eef4ff;color:var(--cool,#175cd3);border-color:#d6e4ff}\n  .wpill.time{background:#fff4ed;color:var(--warm,#b54708);border-color:#f7d9c4}\n  .fitrow{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:11px}\n  .fit{display:inline-flex;align-items:center;gap:6px;font-family:var(--sans);font-weight:600;font-size:12.5px;\n    padding:7px 11px 7px 9px;border-radius:9px;white-space:nowrap;\n    background:var(--grnd-bg,#ecf8f1);color:var(--grnd-deep,#137a4e);border:1px solid var(--grnd-line,#cfe9d9)}\n  .fit .fitic{width:13px;height:13px;flex:none;stroke:currentColor;stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round;fill:none}\n\n  /* footer: solicitation + actions */\n  .cfoot{display:flex;align-items:center;gap:8px}\n  .solno{font-family:var(--mono);font-size:11px;color:var(--faint);flex:1;min-width:0;\n    overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n  .act{font-size:12px;font-weight:600;padding:7px 11px;border-radius:8px;text-decoration:none;\n    border:1px solid var(--line);color:var(--ink);background:#fff;transition:.12s;white-space:nowrap;cursor:pointer}\n  .act:hover{border-color:var(--ink);background:var(--wash)}\n  .act.pri{background:var(--ink);color:#fff;border-color:var(--ink)}\n  .act.pri:hover{background:#233240}\n\n  .empty{text-align:center;padding:48px 24px;color:var(--sub)}\n  .empty h4{font-family:var(--disp);font-size:16px;color:var(--ink);margin-bottom:6px}\n  .empty p{font-size:13.5px;line-height:1.5}\n  .empty button{margin-top:14px;font-size:13px;font-weight:600;padding:9px 16px;border-radius:9px;\n    background:var(--ink);color:#fff;border:none;cursor:pointer}\n\n  /* ============ MAP ============ */\n  .mapwrap{position:relative;min-width:0;min-height:0;display:flex;overflow:hidden}\n  /* Map is a flex child with explicit sizing — no percentage-height chain to break. */\n  #map{flex:1 1 auto;width:100%;min-height:0;align-self:stretch;background:#e8eef2}\n  .leaflet-container{width:100%;height:100%;background:#e8eef2}\n  .maptop{position:absolute;top:14px;left:50%;transform:translateX(-50%);z-index:500;\n    display:flex;gap:8px;align-items:center}\n  .mpill{background:#fff;border:1px solid var(--line);border-radius:999px;padding:8px 15px;\n    font-size:12.5px;font-weight:600;box-shadow:var(--sh2);cursor:pointer;transition:.13s;white-space:nowrap}\n  .mpill:hover{box-shadow:var(--sh3)}\n  .mpill.on{background:var(--ink);color:#fff;border-color:var(--ink)}\n\n  /* Horizon legend — tiny, bottom-left (Eric 2026-08-03: \"people love legends\"). Dots = the exact\n     pin colors. z-index under the bottom-center tile status (520) but above the tiles; bottom-right\n     stays clear for the zoom control. Pointer-events off so it never eats a map drag. TWO variants:\n     the Opportunity map shows horizons (srcColor / --grnd/--recomp/--forecast); the Network map\n     shows entities (contactColorFor / purple #7c3aed, red #dc2626). body.is-network swaps groups. */\n  .maplegend{position:absolute;left:12px;bottom:12px;z-index:500;pointer-events:none;\n    display:flex;align-items:center;background:rgba(255,255,255,.94);\n    border:1px solid var(--line);border-radius:9px;padding:6px 11px;box-shadow:var(--sh2)}\n  .maplegend .lg-grp{display:flex;align-items:center;gap:13px}\n  .maplegend .lg{display:inline-flex;align-items:center;gap:6px;\n    font:600 11px Inter,system-ui,sans-serif;color:var(--ink);white-space:nowrap}\n  .maplegend .lg i{width:9px;height:9px;border-radius:50%;flex:none;box-shadow:0 0 0 1px rgba(0,0,0,.06)}\n  /* one group per map — swap on body.is-network (never both, never neither) */\n  .maplegend .lg-net{display:none}\n  body.is-network .maplegend .lg-opps{display:none}\n  body.is-network .maplegend .lg-net{display:flex}\n  /* Zillow \"Zoom in to see homes\" — country zoom has no pins (Eric 2026-08-12). */\n  .zoomhint{position:absolute;left:12px;top:14px;z-index:510;pointer-events:none;\n    background:#3d4450;color:#fff;font:600 13px Inter,system-ui,sans-serif;\n    padding:8px 12px;border-radius:8px;box-shadow:0 4px 14px rgba(16,24,40,.28);\n    letter-spacing:-.01em}\n  .zoomhint[hidden]{display:none!important}\n  /* Plotted-of-matched count — Zillow's \"500 of 94,509 homes\" pill (Eric 2026-08-13). SAME corner\n     and SAME styling as .zoomhint because the two are MUTUALLY EXCLUSIVE by zoom: far out you get\n     \"Zoom in to see opportunities\", zoomed in you get the count. Sharing the slot is what keeps\n     them from stacking on top of each other. pointer-events:none so it never eats a map drag. */\n  .mapcount{position:absolute;left:12px;top:14px;z-index:510;pointer-events:none;\n    background:#3d4450;color:#fff;font:600 13px Inter,system-ui,sans-serif;\n    padding:8px 12px;border-radius:8px;box-shadow:0 4px 14px rgba(16,24,40,.28);\n    letter-spacing:-.01em}\n  .mapcount[hidden]{display:none!important}\n\n  /* tile load status */\n  .tilestatus{position:absolute;bottom:16px;left:50%;transform:translateX(-50%);z-index:520;\n    background:#fff;border:1px solid var(--line);border-radius:9px;padding:8px 14px;\n    font-size:12.5px;font-weight:500;color:var(--sub);box-shadow:var(--sh2);max-width:78%;\n    text-align:center;display:none}\n  .tilestatus.err{color:#b42318;border-color:#fecdc9;background:#fffbfa}\n\n  .marker-hover{z-index:1000!important}\n\n  /* popup — Google Maps style */\n  .leaflet-popup-content-wrapper{border-radius:14px;box-shadow:var(--sh3);padding:0;overflow:hidden;border:1px solid var(--line)}\n  .leaflet-popup-content{margin:0!important;width:296px!important;line-height:1.45}\n  .leaflet-popup-tip{box-shadow:var(--sh2)}\n  .pv{font-family:var(--ui)}\n  .pv .pvstrip{height:4px}\n  .pv .pvbody{padding:14px 15px 15px}\n  .pv .pvchips{display:flex;align-items:center;gap:6px;margin-bottom:9px;flex-wrap:wrap}\n  /* Title clamped to TWO lines (Eric 2026-08-04) so every card shares an identical rhythm —\n     a long open-opp title can't wrap to 3-4 lines and break the sibling look. */\n  /* The TITLE is the thing being decided on (Eric 2026-08-04: \"the title is competing with the agency\n     … the title should be bigger. It's the thing I'm deciding on.\"). So it's the largest text under the\n     estimate — bigger + heavier than the uppercase agency line, which reads as a quiet label above it. */\n  .pv .pvt{font-family:var(--disp);font-weight:800;font-size:20px;line-height:1.26;\n    letter-spacing:-.4px;color:var(--ink);margin-bottom:6px;\n    display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}\n  /* location = a QUIET secondary label so the title dominates (Eric 2026-08-04: \"Fort McCoy, WI is\n     almost as strong as the title — soften it, make it secondary\"). Smaller, lighter, muted, and\n     capitalized-not-shouted so a SAM ALL-CAPS \"FORT MCCOY, WI\" reads calm. */\n  .pv .pvloc{font-family:var(--sans);font-size:12px;font-weight:500;color:var(--faint);margin-bottom:12px;\n    letter-spacing:.01em;display:flex;align-items:center;gap:5px}\n  .pv .pvloc.noloc{color:var(--faint)}\n  .pv .pvmeta{font-size:13px;color:var(--sub);margin-bottom:12px}\n  .pv .pvmeta b{color:var(--ink);font-weight:600}\n  /* The ONE context sentence that replaces the four-box grid on the popup (slot 5 of the standard):\n     built from the row's own fields, never AI. Set-aside/context chip sits under it. */\n  .pv .pvsent{font-size:13.5px;color:var(--ink);font-weight:600;margin-bottom:10px}\n  .pv .pvsent .lbl{color:var(--sub);font-weight:500}\n  .pv .pvsetwrap{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:13px}\n  .pv .setpill{display:inline-flex;align-items:center;font-family:var(--sans);font-weight:700;font-size:11px;\n    padding:3px 9px;border-radius:999px;background:var(--wash);color:var(--sub);border:1px solid var(--hair)}\n  .pv .setpill.sd{background:#eef2ff;color:#3538cd;border-color:#dfe4ff}\n  .pv .setpill.fore{background:var(--forecast-bg,#f3eefe);color:var(--forecast,#7c5cff);border-color:#e4dcff}\n  /* the tiny forecast-only \"why this is different\" tag */\n  .pv .foretag{font-family:var(--sans);font-weight:600;font-size:11px;color:var(--forecast,#7c5cff);\n    display:inline-flex;align-items:center;gap:5px}\n  .pv .foretag::before{content:\"\";width:5px;height:5px;border-radius:50%;background:var(--forecast,#7c5cff)}\n  .pv .grid2{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-bottom:12px}\n  .pv .fld{background:var(--wash);border:1px solid var(--hair);border-radius:9px;padding:8px 10px}\n  .pv .fld .k{font-family:var(--mono);font-size:9px;letter-spacing:.09em;text-transform:uppercase;color:var(--faint);margin-bottom:3px}\n  .pv .fld .v{font-size:13px;font-weight:600;color:var(--ink)}\n  .pv .fld .v.sd{color:var(--sam)}\n  .pv .fld.wide{grid-column:1/-1}\n  .pv .pvacts{display:flex;gap:8px}\n  .pv .pva{flex:1;text-align:center;font-size:12.5px;font-weight:600;padding:10px;border-radius:9px;\n    text-decoration:none;border:1px solid var(--line);color:var(--ink);background:#fff;transition:.12s}\n  .pv .pva:hover{background:var(--wash);border-color:var(--ink)}\n  .pv .pva.pri{background:var(--ink);color:#fff;border-color:var(--ink)}\n  .pv .pva.pri:hover{background:#233240}\n\n  /* ============ SCOREBOARD (slide-over) ============ */\n  .sbtoggle{position:absolute;top:14px;right:14px;z-index:500;background:var(--score);color:#fff;\n    border:none;border-radius:999px;padding:9px 16px;font-size:12.5px;font-weight:600;cursor:pointer;\n    box-shadow:var(--sh2);display:flex;align-items:center;gap:8px}\n  .sbtoggle b{font-family:var(--disp);color:var(--gold)}\n  .sb{position:absolute;top:0;right:0;bottom:0;width:300px;background:var(--score);color:#fff;\n    z-index:600;padding:20px;overflow-y:auto;transform:translateX(100%);transition:transform .28s cubic-bezier(.4,0,.2,1);\n    box-shadow:-8px 0 24px rgba(16,24,40,.18)}\n  .sb.open{transform:translateX(0)}\n  .sbx{position:absolute;top:14px;right:16px;background:none;border:none;color:#8fb0c9;font-size:19px;cursor:pointer;line-height:1}\n  .sb .lvl{font-family:var(--mono);font-size:10.5px;letter-spacing:.14em;color:#8fb0c9;text-transform:uppercase}\n  .sb .pts{font-family:var(--disp);font-weight:700;font-size:38px;line-height:1;margin-top:4px}\n  .sb .pts small{font-size:13px;color:#8fb0c9;font-weight:500;margin-left:6px}\n  .nb{margin-top:15px}\n  .nb .row{display:flex;justify-content:space-between;font-size:11.5px;color:#b9cdde;margin-bottom:6px}\n  .track{height:6px;background:#1c3a52;border-radius:99px;overflow:hidden}\n  .track>i{display:block;height:100%;background:linear-gradient(90deg,var(--gold),#ffd76a);border-radius:99px;transition:.4s}\n  .quad{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:15px}\n  .qb{background:#12293c;border:1px solid #1f3e57;border-radius:11px;padding:12px;text-align:center}\n  .qb .n{font-family:var(--disp);font-weight:700;font-size:22px;line-height:1}\n  .qb .n.fire{color:var(--fire);display:inline-flex;align-items:center;gap:4px}\n  .qb .n.fire .fireic{width:18px;height:18px}\n  .qb .l{font-family:var(--mono);font-size:9px;letter-spacing:.09em;color:#8fb0c9;text-transform:uppercase;margin-top:5px}\n  .lgt{font-family:var(--mono);font-size:10.5px;letter-spacing:.14em;color:#8fb0c9;text-transform:uppercase;margin:20px 0 9px}\n  .lact{display:flex;justify-content:space-between;align-items:center;background:#12293c;border:1px solid #1f3e57;\n    border-radius:10px;padding:11px 13px;margin-bottom:7px;cursor:pointer;transition:.12s}\n  .lact:hover{background:#173247}\n  .lact .an{font-weight:600;font-size:13px}\n  .lact .av{font-family:var(--disp);font-weight:700;font-size:13.5px;color:#4ade80}\n  .rst{width:100%;background:none;border:none;color:#6f8aa0;font-family:var(--mono);font-size:10.5px;\n    letter-spacing:.1em;padding:13px 0 4px;cursor:pointer}\n  .rst:hover{color:#b9cdde}\n\n  @media(max-width:1000px){\n    .app{grid-template-columns:1fr;grid-template-rows:52vh 48vh}\n    .panel{order:2;border-right:none;border-top:1px solid var(--line)}\n    .mapwrap{order:1}\n    .sb{width:100%}\n  }\n  @media(prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}}\n  :focus-visible{outline:2px solid #2f6fed;outline-offset:2px}\n</style>\n</head>\n<body>\n<!-- Opportunity DNA icons — inline lucide paths (Landmark=agency anchor, Check=SB-friendly). No emoji. -->\n<svg width=\"0\" height=\"0\" style=\"position:absolute\" aria-hidden=\"true\"><defs>\n  <g id=\"dna-landmark\"><path d=\"M4 8 12 4l8 4\"/><line x1=\"4\" y1=\"8\" x2=\"20\" y2=\"8\"/><line x1=\"6\" y1=\"11\" x2=\"6\" y2=\"17\"/><line x1=\"10\" y1=\"11\" x2=\"10\" y2=\"17\"/><line x1=\"14\" y1=\"11\" x2=\"14\" y2=\"17\"/><line x1=\"18\" y1=\"11\" x2=\"18\" y2=\"17\"/><line x1=\"4\" y1=\"20\" x2=\"20\" y2=\"20\"/></g>\n  <g id=\"dna-check\"><path d=\"M20 6 9 17l-5-5\"/></g>\n</defs></svg>\n<div class=\"app\">\n\n  <!-- ========== LEFT PANEL ========== -->\n  <section class=\"panel\">\n    <div class=\"phead\">\n      <div class=\"brandrow\">\n        <div class=\"brand\">Federal Opportunities</div>\n      </div>\n      <div class=\"sumline\" id=\"sumline\"></div>\n    </div>\n\n    <div class=\"fbar\">\n      <div class=\"fscroll\">\n        <button class=\"fbtn\" data-sheet=\"src\">Source <span class=\"cnt\" id=\"c-src\"></span> <span class=\"car\">▼</span></button>\n        <button class=\"fbtn\" data-sheet=\"cat\">Service line <span class=\"cnt\" id=\"c-cat\"></span> <span class=\"car\">▼</span></button>\n        <button class=\"fbtn\" data-sheet=\"set\">Set-aside <span class=\"cnt\" id=\"c-set\"></span> <span class=\"car\">▼</span></button>\n        <button class=\"fbtn\" id=\"f-sd\">SDVOSB only</button>\n        <button class=\"fbtn\" id=\"f-soon\">Closing ≤7 days</button>\n        <button class=\"clr\" id=\"clrAll\">Clear all</button>\n      </div>\n      <div class=\"sheet\" id=\"sheet\"></div>\n    </div>\n\n    <div class=\"sortrow\">\n      <div class=\"rescount\" id=\"rescount\"></div>\n      <select class=\"sortsel\" id=\"sort\">\n        <option value=\"deadline\">Deadline: soonest</option>\n        <option value=\"deadline-far\">Deadline: latest</option>\n        <option value=\"value\">Contract value: high to low</option>\n        <option value=\"az\">Title: A–Z</option>\n      </select>\n    </div>\n\n    <div class=\"feed\" id=\"feed\"></div>\n  </section>\n\n  <!-- ========== MAP ========== -->\n  <div class=\"mapwrap\">\n    <div id=\"map\"></div>\n    <div class=\"zoomhint\" id=\"zoomHint\" hidden>Zoom in to see opportunities</div>\n    <div class=\"mapcount\" id=\"mapCount\" hidden></div>\n    <div class=\"maptop\">\n      <button class=\"mpill\" id=\"fitBtn\">Fit to results</button>\n      <button class=\"mpill\" id=\"basemapBtn\">Terrain</button>\n    </div>\n    <!-- Legend (Eric 2026-08-03: \"people love legends\" — tiny, bottom-left). TWO variants, one per\n         map — the dots match the real pins exactly. Opportunity map = horizons (srcColor:\n         --grnd/--recomp/--forecast). Network map = entities (contactColorFor: contractors purple\n         #7c3aed, gov buyers red #dc2626). body.is-network swaps which group shows (Eric: \"add a\n         Network legend variant instead of hiding\"). -->\n    <div class=\"maplegend\" id=\"mapLegend\" aria-hidden=\"false\">\n      <span class=\"lg-grp lg-opps\">\n        <span class=\"lg\"><i style=\"background:var(--grnd)\"></i>Open</span>\n        <span class=\"lg\"><i style=\"background:var(--recomp)\"></i>Recompete</span>\n        <span class=\"lg\"><i style=\"background:var(--forecast)\"></i>Forecast</span>\n      </span>\n      <span class=\"lg-grp lg-net\">\n        <span class=\"lg\"><i style=\"background:#7c3aed\"></i>Contractors</span>\n        <span class=\"lg\"><i style=\"background:#dc2626\"></i>Gov Buyers</span>\n      </span>\n    </div>\n    <button class=\"sbtoggle\" id=\"sbOpen\">Progress <b id=\"ptsMini\">0</b></button>\n\n    <aside class=\"sb\" id=\"sb\">\n      <button class=\"sbx\" id=\"sbClose\">✕</button>\n      <div class=\"lvl\" id=\"lvlName\">EMERGING</div>\n      <div class=\"pts\"><span id=\"ptsVal\">0</span><small>PTS</small></div>\n      <div class=\"nb\">\n        <div class=\"row\"><span id=\"nextName\">Next: Active Bidder</span><span id=\"nextGap\">250 to go</span></div>\n        <div class=\"track\"><i id=\"lvlFill\" style=\"width:0%\"></i></div>\n      </div>\n      <div class=\"quad\">\n        <div class=\"qb\"><div class=\"n\" id=\"weekPts\">0</div><div class=\"l\">This week</div></div>\n        <div class=\"qb\"><div class=\"n\" id=\"goalTxt\">0/500</div><div class=\"l\">Weekly goal</div></div>\n        <div class=\"qb\"><div class=\"n fire\"><svg class=\"fireic\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 3c1 3 3 4 3 7a3 3 0 0 1-6 0c0-1 .5-2 1-2.5C9 9 8 11 8 13a4 4 0 0 0 8 0c0-4-4-6-4-10z\"/></svg><span id=\"streak\">0</span></div><div class=\"l\">Day streak</div></div>\n        <div class=\"qb\"><div class=\"n\" id=\"best\">0</div><div class=\"l\">Best week</div></div>\n      </div>\n      <div class=\"lgt\">Log an action</div>\n      <div class=\"lact\" data-p=\"1\"><span class=\"an\">Reviewed an opportunity</span><span class=\"av\">+1</span></div>\n      <div class=\"lact\" data-p=\"25\"><span class=\"an\">Recruited a subcontractor</span><span class=\"av\">+25</span></div>\n      <div class=\"lact\" data-p=\"50\"><span class=\"an\">Submitted a bid</span><span class=\"av\">+50</span></div>\n      <div class=\"lact\" data-p=\"500\"><span class=\"an\">Won an award</span><span class=\"av\">+500</span></div>\n      <button class=\"rst\" id=\"resetProg\">RESET PROGRESS</button>\n    </aside>\n  </div>\n</div>\n<button class=\"railbtn\" id=\"railBtn\" title=\"Hide list\" aria-label=\"Hide list\">‹</button>\n\n<script src=\"https://unpkg.com/leaflet@1.9.4/dist/leaflet.js\"></script>\n<script>\n\n// EVC Opportunity Map dataset — Jul 21, 2026\n// Sources: SAM (open/biddable), DLA (supply/parts), RECOMPETE (expiring targets)\n// Coords are approximate city-level lat/lng for map pins.\n\nconst OPPS = __OPPS_JSON__;\n\n\n\n\n</script>\n<script>\n// TODAY = the viewer's ACTUAL local date, anchored to noon so day-diff math (daysOut / postedAgo /\n// \"closes today\") never crosses a boundary due to time-of-day. This WAS hardcoded to 2026-07-21 (a\n// prototype build-time date) — which made every card compute \"days left\" / \"posted N days ago\"\n// against a frozen July 21, so a real Jul-21 opp read \"posted today\" and the drawer disagreed with\n// the card. Now live. (2026-07-27 date-consistency bug.)\nconst TODAY=(function(){var n=new Date();return new Date(n.getFullYear(),n.getMonth(),n.getDate(),12,0,0);})();\n\n// ---------- lookups ----------\nconst CATCOL={\"Janitorial\":\"--jan\",\"Grounds/Landscaping\":\"--grnd\",\"Facility Support\":\"--fac\",\n \"Facility Maint\":\"--maint\",\"Construction/Reno\":\"--con\",\"Engineering/A&E\":\"--ae\",\n \"HVAC/Mechanical\":\"--maint\",\"Roofing/Exterior\":\"--con\",\"Electrical\":\"--ae\",\"IT Services\":\"--it\",\n \"Security Guard\":\"--sec\",\"Training\":\"--train\",\"Healthcare\":\"--health\",\"Heavy Civil\":\"--heavy\",\n \"DLA Supply/Parts\":\"--dla\",\"Painting\":\"--paint\",\"Pest Control\":\"--pest\",\n \"Fencing/Security\":\"--fence\",\"Demolition/Abatement\":\"--demo\"};\nconst AGENCY={VA:\"Veterans Affairs\",DoD:\"Dept of Defense\",GSA:\"General Services Admin\",\n USDA:\"Dept of Agriculture\",DHS:\"Homeland Security\",DOI:\"Dept of the Interior\",\n DOE:\"Dept of Energy\",DOJ:\"Dept of Justice\",DOT:\"Dept of Transportation\",\n HHS:\"Health & Human Services\",\"HHS/FDA\":\"HHS — FDA\",State:\"Dept of State\",AF:\"Air Force\",\n Navy:\"Navy\",Army:\"Army\",USACE:\"Army Corps of Engineers\",USSF:\"Space Force\",DLA:\"Defense Logistics\",\n Commerce:\"Dept of Commerce\",AOC:\"Architect of the Capitol\",IBWC:\"Intl Boundary & Water Comm\",\n USAGM:\"US Agency for Global Media\",\"DoD/Army\":\"Dept of Defense — Army\",SSA:\"Social Security Admin\",\n \"DHS/USCG\":\"Homeland Security — Coast Guard\",\"USDA/FS\":\"Agriculture — Forest Service\",\n DoDEA:\"DoD Education Activity\",\"DOI/NPS\":\"Interior — National Park Service\"};\nconst SETFULL={SDVOSB:\"Service-Disabled Veteran-Owned\",SB:\"Small Business\",\n \"8(a)\":\"8(a) Competed\",EDWOSB:\"Economically Disadv. WOSB\",WOSB:\"Women-Owned Small Business\",\n \"Veteran SA\":\"Veteran-Owned\",ISBEE:\"Indian Small Business\",\n \"Buy Indian\":\"Buy Indian Set-Aside\",None:\"Open / unrestricted\",\"\":\"—\"};\nconst SETGROUPS=[\n {key:\"SDVOSB\",label:\"SDVOSB\",col:\"--grnd\",match:s=>s===\"SDVOSB\"||s===\"Veteran SA\"},\n {key:\"SB\",label:\"Small Business\",col:\"--jan\",match:s=>s===\"SB\"},\n {key:\"8(a)\",label:\"8(a)\",col:\"--fac\",match:s=>s===\"8(a)\"},\n {key:\"EDWOSB\",label:\"WOSB / EDWOSB\",col:\"--con\",match:s=>s===\"EDWOSB\"||s===\"WOSB\"},\n {key:\"Other\",label:\"Other set-aside\",col:\"--train\",match:s=>[\"ISBEE\",\"Buy Indian\"].includes(s)},\n {key:\"None\",label:\"Unrestricted\",col:\"--sec\",match:s=>s===\"None\"||s===\"\"}];\nconst SRCLABEL={SAM:\"Open on SAM\",RECOMPETE:\"Target\",DLA:\"DLA supply\",SBIR:\"SBIR/STTR\",FORECAST:\"Forecast\",GRANTS:\"Grant\"};\n\nfunction cv(v){return getComputedStyle(document.documentElement).getPropertyValue(v).trim();}\nfunction catColor(c){return cv(CATCOL[c]||\"--sec\");}\n// Pin/card color by SOURCE: RECOMPETE=amber, SBIR=purple (a distinct source, like DLA), else by category.\nfunction srcColor(o){/* PIN COLOR = TIME HORIZON only (Eric 2026-07-30, map-as-app): open=green, recompete=amber, forecast=violet. SOURCE (SAM/DLA/SBIR/Grants) is NOT a color — it lives in the source filter + card, so the map stays calm and scales to any number of sources. SBIR used to be violet (a source cue); it is an OPEN opp, so it is now green like every other open pin. */return o.src==='RECOMPETE'?cv('--recomp'):(o.src==='FORECAST'?cv('--forecast'):cv('--grnd'));}\nfunction setKey(s){for(const g of SETGROUPS)if(g.match(s))return g.key;return \"None\";}\n// Compact money for the DECISION-CARD hero (Eric 2026-08-03: the card leads with the number, like a\n// Zillow price). \"$4.9M\" / \"$540K\" — same rounding the map PIN uses (mCompact), so the tag on the pin\n// and the hero on the card always agree. n<=0 / not-finite → '' (caller shows \"Estimate Pending\" —\n// NEVER a fabricated number, mirroring value-range.ts's ≥8-comps-or-nothing contract).\nfunction estMoney(n){n=Number(n);if(!isFinite(n)||n<=0)return '';\n  if(n>=1e9)return '$'+(n/1e9).toFixed(n%1e9?1:0).replace(/\\.0$/,'')+'B';\n  if(n>=1e6)return '$'+(n/1e6).toFixed(n%1e6?1:0).replace(/\\.0$/,'')+'M';\n  if(n>=1e3)return '$'+Math.round(n/1e3)+'K';\n  return '$'+Math.round(n);}\n// EXACT card money — matches the drawer hero's fmtM (Eric 2026-08-04: \"I like the exact number\n// better\"). Sub-$1M shows the full figure ($479,084) instead of estMoney's rounded $479K, so the\n// rail card equals the drawer. >=$1M stays $X.XM / $X.XB (the drawer does the same — a full\n// $2,200,000 reads worse than $2.2M and the drawer already abbreviates there). The tiny MAP-PIN\n// bubble keeps estMoney/mCompact — a full number overflows a map label (Zillow abbreviates the dot,\n// shows the exact price on the listing).\nfunction estMoneyExact(n){n=Number(n);if(!isFinite(n)||n<=0)return '';\n  if(n>=1e9)return '$'+(n/1e9).toFixed(1)+'B';\n  if(n>=1e6)return '$'+(n/1e6).toFixed(1)+'M';\n  return '$'+Math.round(n).toLocaleString();}\n// The estimate HERO block that leads every open-opp / forecast card. The ≈ is the one honest glyph\n// that says \"estimate, not a quoted price\" (Eric: Zillow shows a price, ours is an estimate). No\n// \"M-Estimate\" label on the card — the branding + methodology live in the LISTING. RECOMPETE rows\n// lead with the real CONTRACT VALUE (o.value, a firm number) instead — labeled honestly, no ≈.\n// No grounded value (<8 comps → o.est falsy) → a quiet \"Estimate Pending\", never a fake number.\nfunction cardHero(o){\n  if(o.src==='RECOMPETE'){\n    // EXACT contract value, not the rounded $575K (Eric 2026-08-05: \"can we not round up the\n    // numbers\"). o.valueNum is the raw USASpending ceiling (potential_total_value, 100% populated);\n    // estMoneyExact prints the full figure sub-$1M ($575,284) and $X.XM above — the SAME formatter\n    // the open-opp card uses, so recompete + open read identically. Fall back to the pre-formatted\n    // o.value string only when the raw number is absent (never regress to blank).\n    var cv=(Number(o.valueNum)>0)?estMoneyExact(o.valueNum):((o.value&&String(o.value).trim())?String(o.value):'');\n    return cv\n      ? '<div class=\"chero recomp\"><div class=\"cval\">'+cv+'</div></div>'\n      : '<div class=\"chero pending\"><div class=\"cval pend\">Value on file at SAM</div></div>';\n  }\n  // FORECAST leads with the AGENCY's OWN published estimate — a REAL government figure, so NO ≈\n  // glyph (Eric 2026-08-04: \"the forecast should have real numbers not modeled\"). The ≈ is\n  // reserved for an OPEN opp's MODELED estimate. estRange is verbatim from agency_forecasts\n  // (e.g. \"$5M - $9.9M\"); '' when the agency published nothing → an honest \"Estimate pending\".\n  if(o.src==='FORECAST'){\n    var er=(o.estRange&&String(o.estRange).trim())?String(o.estRange):'';\n    return er\n      ? '<div class=\"chero fore\"><div class=\"cval\">'+esc(er)+'</div></div>'\n      : '<div class=\"chero pending\"><div class=\"cval pend\">Estimate pending</div></div>';\n  }\n  var m=estMoneyExact(o.est); // EXACT on the card (matches drawer)\n  var conf=confSub(o); // the grounded \"Likely $Low–$High\" line, INSIDE the box (see confSub; Eric 2026-08-05)\n  return m\n    ? '<div class=\"chero\"><div class=\"cval\"><span class=\"apx\">≈ </span>'+m+'</div>'+conf+'</div>'\n    : '<div class=\"chero pending\"><div class=\"cval pend\">Estimate Pending</div></div>';\n}\n// The tiny confidence sub-line rendered INSIDE .chero. Grounded, OPEN only. (Split from confLine so\n// the string is reused by the popup too.)\nfunction confSub(o){\n  if(o.src==='RECOMPETE'||o.src==='FORECAST') return '';\n  if(!(Number(o.est||0)>0)) return '';\n  // The confidence line is the COMPARABLE-AWARD COUNT — \"Estimated from N similar awards\" (Eric\n  // 2026-08-05: \"that's what we want, not the value range\"). Grounded (o.estN, the real count of\n  // comparables behind the estimate); shown only when we have a count; nothing otherwise (no fabrication).\n  var n=Number(o.estN||0);\n  if(n>0) return '<div class=\"cconf\">Estimated from '+n.toLocaleString('en-US')+' similar awards</div>';\n  return '';\n}\nfunction dueDate(o){return o.src==='RECOMPETE'?o.exp:o.close;}\n// Anchor the due date to local NOON (matching TODAY) so the day-diff is a clean integer, not\n// offset by a midnight-vs-noon half day that Math.round could flip. dueDate is a YYYY-MM-DD string.\nfunction daysOut(o){var d=String(dueDate(o)||'').slice(0,10); if(!d)return NaN; return Math.round((new Date(d+'T12:00:00')-TODAY)/864e5);}\nfunction valNum(o){ // for sorting\n  if(!o.value)return -1;\n  const m=o.value.match(/([\\d.]+)\\s*([KM])/i);if(!m)return -1;\n  return parseFloat(m[1])*(m[2].toUpperCase()==='M'?1e6:1e3);\n}\nfunction fmtDays(d,isRecompete){\n  // RECOMPETE rows measure \"days out\" against the CONTRACT EXPIRATION. These are LIVE\n  // subcontracting + recompete opportunities, never dead/expired notices — so the status\n  // language INVITES pursuit (\"Recompete now\", \"subcontract\"), and never uses 'dead'/greyed\n  // styling or the words \"Expired\"/\"Closed\" (which read as unavailable). The Expires DATE still\n  // shows in its own field (it's the selling point — this comes up for rebid), but the STATUS\n  // pill frames the card as an opportunity.\n  if(isRecompete){\n    // The dataset tab is already named \"Recompetes\" — so the pill must NOT echo it (Eric 2026-07-27:\n    // \"the cards still say recompetes at the top\"). It carries the TIMING the Expires date can't flag\n    // at a glance: how close the rebid is. (The recompete FRAME is the tab; the pill = urgency only.)\n    // PAST-EXPIRY is honest here: a contract whose end already passed did NOT \"expire now\" — it\n    // EXPIRED, the recompete already left (Eric 2026-07-27, the NRWA case). The default view filters\n    // these out (recompete-map ?includePast); this label covers the ones that surface via favorites /\n    // saved search / deep link so they never read as a live window.\n    if(d<0)return{t:'Expired',c:'cool'};                    // end date already passed → recompete gone\n    if(d<=90)return{t:'Expiring soon',c:'warm'};            // rebid within ~90 days — the sweet spot\n    return{t:'Active — subcontract',c:'cool'};              // still running → pursue as a sub today\n  }\n  if(d<0)return{t:'Closed',c:'dead'};\n  if(d===0)return{t:'Due today',c:'hot'};\n  if(d===1)return{t:'1 day left',c:'hot'};\n  if(d<=3)return{t:d+' days left',c:'hot'};\n  if(d<=7)return{t:d+' days left',c:'warm'};\n  return{t:d+' days left',c:'cool'};\n}\n// Noon-anchor the calendar date so a UTC-midnight / date-only value doesn't shift a day in US zones.\nfunction longDate(d){var s=String(d||'').slice(0,10); if(!s)return ''; return new Date(s+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});}\n// Card-cell date: DROP the year ONLY when it's the current year (keeps near-term cells compact), but\n// ALWAYS show it otherwise. Eric 2026-07-27: a card read \"Expires Apr 30\" with no year on a contract\n// whose follow-on runs to 2030 — ambiguous 2026-vs-2027-vs-2030, and the year is load-bearing on a\n// recompete. Blanket-stripping \", 2026\" was wrong the moment a date wasn't in 2026. '' if undated.\nfunction shortDate(d){var s=String(d||'').slice(0,10); if(!s)return ''; var dt=new Date(s+'T12:00:00');\n  if(isNaN(dt))return ''; var y=dt.getFullYear();\n  // Show the year UNLESS it's the current year AND still in the future (compact for near-term rows).\n  // A PAST date always shows its year so an expired contract can't read as this-year-and-fine.\n  var compact = (y===TODAY.getFullYear()) && (dt>=TODAY);\n  return dt.toLocaleDateString('en-US', compact?{month:'short',day:'numeric'}:{month:'short',day:'numeric',year:'numeric'});}\n// \"Posted 3 days ago\" freshness (Zillow's \"12 minutes ago\" badge). Uses the CALENDAR date vs TODAY\n// (both local noon) so it can't read \"posted today\" for a day-old opp. '' if undated.\nfunction postedAgo(v){ var s=String(v||'').slice(0,10); if(!s)return ''; var t=Date.parse(s+'T12:00:00'); if(!isFinite(t))return '';\n  var days=Math.floor((TODAY-t)/864e5); if(days<0)days=0;\n  if(days===0)return 'Posted today'; if(days===1)return 'Posted 1 day ago';\n  if(days<30)return 'Posted '+days+' days ago';\n  var mo=Math.floor(days/30); return 'Posted '+mo+' month'+(mo===1?'':'s')+' ago'; }\n// Real award TYPE label for an Awarded card (IDIQ vehicle / Task order / …) from contract_type —\n// the UNIQUE lead badge, replacing the identical \"Target\" every recompete card used to show.\n// Mirrors contractTypeLabel() in the drawer JS; kept inline because template.html has its own scope.\nfunction awardTypeBadge(ct){ var t=String(ct||'').toUpperCase().trim(); if(!t)return '';\n  if(t.indexOf('IDV')>=0||t.indexOf('IDIQ')>=0||t.indexOf('INDEFINITE')>=0||t==='GWAC'||t==='BPA')return 'IDIQ vehicle';\n  if(t.indexOf('DELIVERY ORDER')>=0||t.indexOf('TASK ORDER')>=0)return 'Task order';\n  if(t.indexOf('BPA CALL')>=0)return 'BPA call';\n  if(t.indexOf('PURCHASE ORDER')>=0)return 'Purchase order';\n  if(t.indexOf('DEFINITIVE')>=0)return 'Definitive contract'; return ''; }\n// The card's LEAD badge = UNIQUE per-card info, NOT a repeated dataset label (the section header +\n// the card's color strip already say the dataset — Eric/Zillow 2026-07-27). Open → posted freshness;\n// Awarded → the real award type. Falls back to the source label only if the unique field is absent.\nfunction cardBadge(o){\n  if(o.src==='RECOMPETE'){ var at=awardTypeBadge(o.contractType); return at||''; }\n  var pa=postedAgo(o.posted); return pa||'';\n}\n// EARLY-SIGNAL chip — does this office telegraph work BEFORE it hits the street?\n// Scored per buying office (the DoDAAC that prefixes the solicitation number):\n// 46 offices are >=50% early while 115 post ZERO early notices, so the\n// department average (21.2%) describes almost nobody. The behavioural read is\n// the product: 'high' → the requirement can still be shaped, go build the\n// relationship; low/none → nothing to influence, just bid it when it posts.\n// Only high/medium earn a chip — \"this office never posts early\" is not news on\n// every card, and a chip on 470 offices would be wallpaper.\nfunction earlySignalChip(o){\n  if(o.earlySignal!=='high'&&o.earlySignal!=='medium')return '';\n  var t=o.earlySignal==='high'?'Posts early':'Sometimes early';\n  // Percent goes in the tooltip, not the label: the rate moves ~10.7 points\n  // between periods, so a precise number on the card would imply false accuracy.\n  var pct=typeof o.earlySignalPct==='number'?o.earlySignalPct+'% of this office’s notices are sources-sought or presolicitation — the window where you can still shape the requirement.':'';\n  return '<span class=\"chip early '+o.earlySignal+'\" title=\"'+pct+'\">'+t+'</span>';\n}\nfunction samURL(o){return 'https://sam.gov/search/?keywords='+encodeURIComponent(o.sol);}\n// A RECOMPETE row is one of TWO plays (Eric 2026-07-27): a still-running TASK ORDER under a live\n// IDIQ → you can't prime it now, so the play is SUBCONTRACT to the incumbent today; vs an EXPIRING\n// prime award → get ahead of the RECOMPETE and bid it next cycle. fmtDays' 'cool' bucket\n// (\"Active — subcontract\") is exactly the subcontract case; 'warm'/'hot' is the recompete case.\nfunction recompetePlay(o){\n  if(o.src!=='RECOMPETE')return null;\n  var f=fmtDays(daysOut(o),true);\n  return f.c==='cool'?'subcontract':'recompete';\n}\nfunction draftURL(o){\n  var play=recompetePlay(o);\n  var p;\n  if(play==='subcontract')\n    p=`Help my small business win subcontract work on an active federal contract. Prime/incumbent: ${o.title}. Agency: ${o.agency}. Location: ${o.loc}. Contract value: ${o.value||'n/a'}. Expiration: ${o.exp}. Contract/order #: ${o.sol}. NAICS ${o.naics}. Find the prime's small-business liaison, tell me what they likely subcontract, and draft an outreach approach to team with them while this contract is running.`;\n  else if(play==='recompete')\n    p=`Help me prepare my small business capture strategy for an expiring federal contract I want to recompete. Incumbent: ${o.title}. Agency: ${o.agency}. Location: ${o.loc}. Current value: ${o.value||'n/a'}. Expiration: ${o.exp}. Prior solicitation #: ${o.sol}. NAICS ${o.naics}. Find the likely follow-on solicitation, assess win probability, and outline a teaming + differentiation plan.`;\n  else\n    p=`Help me draft a federal bid response for my small business. Opportunity: ${o.title}. Agency: ${o.agency}. Set-aside: ${o.set}. Location: ${o.loc}. NAICS ${o.naics}. Solicitation #: ${o.sol}. Response due ${o.close}. Pull the solicitation, build a compliance matrix, and draft our approach.`;\n  return 'https://claude.ai/new?q='+encodeURIComponent(p);\n}\n// The primary CTA label matches the play: subcontract rows say \"Plan outreach\" (reach the incumbent),\n// recompete rows say \"Plan recompete\", open opps say \"Start drafting\".\nfunction draftCTA(o){var play=recompetePlay(o);return play==='subcontract'?'Plan outreach':play==='recompete'?'Plan recompete':'Start drafting';}\n\n// ---------- state ----------\n// CATS + the src facet list are DYNAMIC — the Opportunities map merges 5 sources (SAM/DLA/SBIR\n// opens + FORECAST + GRANTS) and their categories aren't known at SSR time. refreshFacets()\n// (called after every fetch) unions any NEW src/cat found in the live OPPS into the filter sets,\n// SELECTED by default — otherwise pass()'s `F.src.has`/`F.cat.has` checks silently reject every\n// pin from a source the frozen sets never heard of (the bug that hid ALL DLA/Forecast/Grant pins:\n// they loaded into OPPS but pass() dropped 100% of them). (Eric 2026-07-31.)\nlet CATS=[...new Set(OPPS.map(o=>o.cat))].sort((a,b)=>cnt('cat',b)-cnt('cat',a));\nfunction cnt(k,v){return OPPS.filter(o=>k==='cat'?o.cat===v:k==='src'?o.src===v:setKey(o.set)===v).length;}\nconst ALL_SRC=[\"SAM\",\"DLA\",\"SBIR\",\"FORECAST\",\"GRANTS\",\"RECOMPETE\"];\nconst F={src:new Set(ALL_SRC),cat:new Set(CATS),set:new Set(SETGROUPS.map(g=>g.key)),\n         sdOnly:false,soon:false,sort:''};\n// Union any src/cat present in the live OPPS into the (selected) filter sets + refresh CATS, so a\n// newly-loaded horizon renders instead of being silently filtered out. Only ADDS (never removes a\n// user's deselection of a value that's still present). Safe to call every render.\nfunction refreshFacets(){\n  try{\n    (OPPS||[]).forEach(function(o){ if(o&&o.src&&!F.src.has(o.src))F.src.add(o.src); });\n    var live=[...new Set((OPPS||[]).map(function(o){return o.cat;}).filter(Boolean))];\n    live.forEach(function(c){ if(!F.cat.has(c))F.cat.add(c); });\n    CATS=live.sort(function(a,b){return cnt('cat',b)-cnt('cat',a);});\n  }catch(e){}\n}\nlet rows=[],markers=new Map(),selected=null;\n\n// ---------- filter sheets ----------\nconst sheet=document.getElementById('sheet');\nlet openSheet=null;\ndocument.querySelectorAll('.fbtn[data-sheet]').forEach(b=>{\n  b.onclick=()=>{const k=b.dataset.sheet;\n    if(openSheet===k){closeSheet();return;}\n    document.querySelectorAll('.fbtn[data-sheet]').forEach(x=>x.classList.remove('open'));\n    b.classList.add('open');openSheet=k;renderSheet(k);sheet.classList.add('show');};\n});\nfunction closeSheet(){openSheet=null;sheet.classList.remove('show');\n  document.querySelectorAll('.fbtn[data-sheet]').forEach(x=>x.classList.remove('open'));}\nfunction renderSheet(k){\n  let items,title;\n  if(k==='src'){title='Where it came from';\n    items=[\"SAM\",\"RECOMPETE\",\"DLA\",\"SBIR\"].map(v=>({v,label:SRCLABEL[v],col:v==='SAM'?'--sam':v==='DLA'?'--dlac':v==='SBIR'?'--sbir':'--recomp',n:cnt('src',v)}));}\n  else if(k==='cat'){title='Service line';\n    items=CATS.map(v=>({v,label:v,col:CATCOL[v],n:cnt('cat',v)}));}\n  else{title='Set-aside eligibility';\n    items=SETGROUPS.map(g=>({v:g.key,label:g.label,col:g.col,n:cnt('set',g.key)})).filter(i=>i.n>0);}\n  sheet.innerHTML=`<h5>${title}</h5><div class=\"optgrid\">`+\n    items.map(i=>`<div class=\"opt ${F[k].has(i.v)?'on':''}\" data-v=\"${i.v}\">\n      <span class=\"cbx\"><svg viewBox=\"0 0 12 12\"><path d=\"M2 6.5l2.5 2.5L10 3.5\"/></svg></span>\n      <span class=\"swatch\" style=\"background:${cv(i.col)}\"></span>\n      <span class=\"lbl\">${i.label}</span><span class=\"n\">${i.n}</span></div>`).join('')+\n    `</div><div class=\"sheetfoot\">\n      <button class=\"sfb\" data-all=\"0\">Clear</button>\n      <button class=\"sfb pri\" data-all=\"1\">Select all</button></div>`;\n  sheet.querySelectorAll('.opt').forEach(el=>{\n    el.onclick=()=>{const v=el.dataset.v;\n      F[k].has(v)?F[k].delete(v):F[k].add(v);el.classList.toggle('on');render();};\n  });\n  sheet.querySelectorAll('.sfb').forEach(b=>{\n    b.onclick=()=>{F[k].clear();\n      if(b.dataset.all==='1')items.forEach(i=>F[k].add(i.v));\n      renderSheet(k);render();};\n  });\n}\n// Null-safe boot binds (2026-08-04): every one of these runs at TOP-LEVEL map init, so if its element\n// has been renamed/removed by another change (the legacy filter bar — f-sd/f-soon/clrAll/sort — no\n// longer ships in the current top-bar UI), an unguarded `getElementById(id).onclick=` throws\n// \"Cannot set properties of null\" and aborts the REST of init — which then makes fetchView's render\n// throw, surfacing the false \"Couldn't load this view / network hiccup\" on every cold load. bindEl\n// no-ops on a missing element so one absent control can never brick the whole map again.\nfunction bindEl(id,ev,fn){var el=document.getElementById(id); if(el)el[ev]=fn; return el;}\nbindEl('f-sd','onclick',e=>{F.sdOnly=!F.sdOnly;e.target.classList.toggle('active',F.sdOnly);render();});\nbindEl('f-soon','onclick',e=>{F.soon=!F.soon;e.target.classList.toggle('active',F.soon);render();});\nbindEl('clrAll','onclick',()=>{\n  F.src=new Set(ALL_SRC);F.cat=new Set(CATS);F.set=new Set(SETGROUPS.map(g=>g.key));\n  F.sdOnly=false;F.soon=false;\n  var _fsd=document.getElementById('f-sd'); if(_fsd)_fsd.classList.remove('active');\n  var _fso=document.getElementById('f-soon'); if(_fso)_fso.classList.remove('active');\n  if(openSheet)renderSheet(openSheet);render();});\nbindEl('sort','onchange',e=>{F.sort=e.target.value;render();});\n\n// ---------- map ----------\nfunction __inUS(lat,lng){\n  if(typeof lat!=='number'||typeof lng!=='number')return false;\n  if(lat>=24&&lat<=50&&lng>=-125&&lng<=-66)return true; // CONUS\n  if(lat>=51&&lat<=72&&lng>=-180&&lng<=-129)return true; // AK\n  if(lat>=18&&lat<=23&&lng>=-161&&lng<=-154)return true; // HI\n  if(lat>=17&&lat<=19&&lng>=-68&&lng<=-64)return true;   // PR\n  return false;\n}\nfunction __lastMapView(){\n  try{\n    var raw=localStorage.getItem('mi_map_last_view');\n    if(!raw)return null;\n    var v=JSON.parse(raw);\n    if(!v||typeof v.lat!=='number'||typeof v.lng!=='number')return null;\n    if(!__inUS(v.lat,v.lng))return null; // federal map — never restore a view outside the US\n    var z=typeof v.z==='number'?v.z:5;   // 5 = PIN_DOT_ZOOM; below it the map draws NO pins\n    if(z<4)return null;\n    if(v.t&&(Date.now()-v.t)>30*24*3600*1000)return null;\n    return {c:[v.lat,v.lng],z:z};\n  }catch(e){return null;}\n}\nvar __lv=__lastMapView();\n// NO minZoom — Zillow parity (Eric 2026-08-12: \"drop the minzoom, handle like zillow\").\n// The clamp made the zoom-out button DEAD at the bottom of its range, which reads as broken\n// rather than as a boundary. Zillow lets you zoom to the continent and simply stops drawing\n// pins, showing \"Zoom in to see homes.\" — we already do exactly that below PIN_DOT_ZOOM=5\n// via the .zoomhint pill, so the clamp was protecting against a state that is already handled.\nconst map=L.map('map',{scrollWheelZoom:true,zoomControl:false,worldCopyJump:true,\n  zoomSnap:.5}).setView(__lv?__lv.c:[38,-96], __lv?__lv.z:5);   // 5 = PIN_DOT_ZOOM (see route.ts CONUS)\nL.control.zoom({position:'bottomright'}).addTo(map);\n// Tile providers must be keyless and return real map imagery (not watermarked 200s).\n// CARTO Voyager was retired from this list: keyless basemaps.cartocdn.com now serves\n// HTTP 200 PNGs stamped \"API KEY REQUIRED\", which Leaflet treats as success so the\n// tileerror fallback never fires. Only providers with keyless:true may boot or cycle.\nconst PROVIDERS=[\n  {name:'Streets', url:'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',\n   sub:'abc', attr:'&copy; OpenStreetMap contributors', keyless:true},\n  {name:'Terrain', url:'https://{s}.tile.opentopomap.org/{z}/{x}/{y}.png',\n   sub:'abc', attr:'&copy; OpenTopoMap, &copy; OpenStreetMap', keyless:true},\n];\nlet provIdx=0, tiles=null, okTiles=0;\n\nfunction mountTiles(i){\n  let idx=i;\n  while(idx<PROVIDERS.length && !PROVIDERS[idx].keyless) idx++;\n  if(idx>=PROVIDERS.length){\n    setTileStatus('Map tiles unavailable. Pins still work — try the basemap button.','err');\n    return;\n  }\n  if(idx!==i) provIdx=idx;\n  const p=PROVIDERS[idx];\n  if(tiles)map.removeLayer(tiles);\n  okTiles=0;\n  setTileStatus('Loading '+p.name+' tiles…','load');\n  tiles=L.tileLayer(p.url,{maxZoom:19,subdomains:p.sub,attribution:p.attr});\n  let errs=0;\n  tiles.on('tileload',()=>{okTiles++;if(okTiles===1)setTileStatus('','ok');});\n  tiles.on('tileerror',()=>{\n    errs++;\n    if(errs>=6 && okTiles===0){\n      if(idx+1<PROVIDERS.length){provIdx=idx+1;mountTiles(provIdx);}\n      else setTileStatus('Map tiles blocked by your network. Pins still work — try the basemap button.','err');\n    }\n  });\n  tiles.addTo(map);\n  const b=document.getElementById('basemapBtn');\n  if(b)b.textContent=PROVIDERS[(idx+1)%PROVIDERS.length].name;\n}\nfunction setTileStatus(msg,kind){\n  let el=document.getElementById('tileStatus');\n  if(!el){el=document.createElement('div');el.id='tileStatus';el.className='tilestatus';\n    document.querySelector('.mapwrap').appendChild(el);}\n  el.textContent=msg;\n  el.className='tilestatus'+(kind==='err'?' err':'');\n  el.style.display=msg?'block':'none';\n}\nmountTiles(0);\nbindEl('basemapBtn','onclick',()=>{\n  provIdx=(provIdx+1)%PROVIDERS.length;mountTiles(provIdx);\n});\n// Robust sizing. Percentage-height chains break inside grid/flex in some browsers,\n// so we measure the wrapper and set an explicit pixel height on #map.\nconst mapEl=document.getElementById('map'),wrapEl=document.querySelector('.mapwrap');\nfunction resize(){\n  const h=wrapEl.clientHeight||wrapEl.getBoundingClientRect().height;\n  const w=wrapEl.clientWidth||wrapEl.getBoundingClientRect().width;\n  if(h>0)mapEl.style.height=h+'px';\n  else mapEl.style.height=Math.max(400,window.innerHeight-0)+'px'; // last-resort fallback\n  if(w>0)mapEl.style.width=w+'px';\n  map.invalidateSize({animate:false});\n}\n[0,50,120,250,450,800,1400].forEach(t=>setTimeout(resize,t));\n/* Zillow opens to YOUR area, not the whole world (Eric 2026-08-04). The boot fitView() fit all\n   markers — including global outliers — so the map opened at world zoom. BOOT_VIEW_JS now owns the\n   initial view (centers on the signed-in user's home state, else CONUS); this load handler only\n   resizes. window.__suppressFitView makes fitView() a no-op until BOOT_VIEW has placed the view. */\nwindow.addEventListener('load',()=>{resize();setTimeout(resize,140);});\nwindow.addEventListener('resize',resize);\nif(window.ResizeObserver){\n  new ResizeObserver(resize).observe(wrapEl);\n}\n// Value-tag pins (Zillow price-tag model): render tags DIRECTLY into a plain layerGroup — NO\n// clustering by default. Zillow does not cluster; it shows a dense field of $-tag pins that\n// overlap on purpose (the wall of numbers is the product — \"$4.5M next to $335K\"). The selected/\n// hovered tag rises to front + scales up. (Superseded the markercluster container from #461.)\nconst layer=L.layerGroup().addTo(map);\n// Null-guard the Fit bind (2026-08-04): this runs at top-level map init, so a MISSING #fitBtn threw\n// \"Cannot set properties of null (setting 'onclick')\" here — which aborted the rest of init and made\n// fetchView's render throw, so the feed showed \"Couldn't load this view / network hiccup\" on EVERY\n// cold load even though the API returned 200. A single unguarded getElementById at boot can take the\n// whole map down; guard it so a renamed/removed control can never brick initialization again.\nbindEl('fitBtn','onclick',()=>fitView(true));   // manual \"Fit\" always fits (bypasses the boot guard) — null-safe (see bindEl)\nfunction fitView(force){\n  // Boot guard (Eric 2026-08-04): during initial boot BOOT_VIEW_JS owns the view (user's home\n  // state / CONUS), so an un-forced fitView() is a no-op — otherwise it re-fits ALL markers,\n  // including global outliers, and blows the map back out to world zoom. `force` (the Fit button,\n  // an explicit search) still fits.\n  if(!force && window.__suppressFitView) return;\n  const ms=[...markers.values()];if(!ms.length)return;\n  const s=map.getSize();\n  if(s.x<50||s.y<50){setTimeout(()=>fitView(force),200);return;} // map not laid out yet\n  map.fitBounds(L.featureGroup(ms).getBounds().pad(.16),{animate:false,maxZoom:8});\n  // Overseas outliers (Sasebo, embassies) must never blow the map out of the United States.\n  var c=map.getCenter();\n  if(!c||!__inUS(c.lat,c.lng)||map.getZoom()<4){ try{ map.setView([38,-96],5,{animate:false}); }catch(e){} }   // 5 = PIN_DOT_ZOOM\n}\n\n// ---------- popup (Google-Maps style) ----------\n// The map-pin POPUP speaks the SAME card language as the result-list card (Eric 2026-08-03,\n// \"identity first, size second\"): it REUSES lcHeader / dnaRow / cardHero / fitChips so the pin,\n// the card and the popup can never disagree. Order mirrors cardHTML exactly —\n//   lifecycle header -> IDENTITY (dnaRow) -> value HERO (cardHero) -> chips -> title -> full-agency\n//   meta -> fit chips -> facts -> solicitation -> CTAs.\n// Three Eric decisions locked here:\n//  1. DNA identity leads; the value comes SECOND (cardHero), never first.\n//  2. RECOMPETE value is the REAL contract number (cardHero → o.value, NO ≈); only OPEN/forecast\n//     get the ≈ M-Estimate band (cardHero → estMoney(o.est)). cardHero owns the ≈-glyph rule, so\n//     the popup can't diverge from the card.\n//  3. The \"Current incumbent\" line is DROPPED when the incumbent equals the card title (a recompete\n//     row's title IS the incumbent → the line would just repeat the title). It shows ONLY when a\n//     genuine, DIFFERENT incumbent exists on the row (case-insensitive, trimmed compare).\n// The ONE context sentence (slot 5) — built ENTIRELY from the row's own fields, never AI (Eric\n// 2026-08-04). Forecast: \"Planned for <Q# FY####>\" · Open: \"Due <date> · Posted <date>\" ·\n// Recompete: \"Incumbent expires <date>\". Dates are Posted-style short dates that age well\n// (Eric: \"Posted 13 days ago ages poorly. Dates don't.\").\nfunction pvSentence(o){\n  if(o.src==='RECOMPETE'){\n    return o.exp ? '<b>Incumbent expires '+esc(longDate(o.exp))+'</b>' : '';\n  }\n  if(o.src==='FORECAST'){\n    // timing rides o.cat as \"Forecast · Q2 FY2026\"; else the anticipated award date; else nothing.\n    var t=String(o.cat||'').split('·').pop().trim();\n    if(t && !/^forecast$/i.test(t)) return '<b>Planned for '+esc(t)+'</b>';\n    return o.close ? '<b>Planned for '+esc(longDate(o.close))+'</b>' : '';\n  }\n  // OPEN opps: the popup no longer renders this sentence at all (Eric 2026-08-04) — \"Posted <date>\"\n  // already rides the lifecycle header, and the deadline is the \"✓ Due in N days\" whyChip, so a Due/\n  // Posted sentence here was the duplicate \"Posted Jul 21\". The result-list CARD still calls\n  // pvSentence, so keep computing the string for that caller; only the popup drops it (see popupHTML).\n  var hasDueChip = !!dueChip(o);\n  var due=(!hasDueChip && o.close)?('<b>Due '+esc(shortDate(o.close))+'</b>'):'';\n  var posted=o.posted?('<span class=\"lbl\">Posted '+esc(shortDate(o.posted))+'</span>'):'';\n  return due && posted ? (due+' &middot; '+posted) : (due || posted);\n}\n// The single set-aside / context chip row (slot 5 tail). Open → the real set-aside (or \"Open\n// competition\"). Forecast → \"Open competition\" + the \"Not yet on SAM.gov\" differentiator tag.\n// Recompete → NOTHING (Eric 2026-08-04: removed \"Win odds\" — no competing scoring language on\n// the card; win probability lives in the listing).\n// Client mirror of genome.ts setAsideLabel — names the program (\"WOSB\" -> \"WOSB Set-Aside\"), used on\n// the forecast pill (forecasts have no DNA set_aside chip to carry it). Keep in sync with genome.ts.\nfunction setAsideLabel(set){\n  var k=String(set==null?'':set).toUpperCase().trim();\n  var M={SDVOSB:'SDVOSB Set-Aside','VETERAN SA':'Veteran-Owned Set-Aside',VOSB:'Veteran-Owned Set-Aside',SB:'Small Business Set-Aside','8A':'8(a) Set-Aside','8(A)':'8(a) Set-Aside',WOSB:'WOSB Set-Aside',EDWOSB:'EDWOSB Set-Aside',HZ:'HUBZone Set-Aside',HUBZONE:'HUBZone Set-Aside',ISBEE:'Indian SB Set-Aside','BUY INDIAN':'Indian SB Set-Aside',OTHER:'Set-Aside'};\n  return M[k]||(k?k+' Set-Aside':'Set-Aside');\n}\nfunction pvSetRow(o){\n  if(o.src==='RECOMPETE')return '';\n  var hasSet=o.set && o.set!=='None' && o.set!=='NONE';\n  if(o.src==='FORECAST'){\n    // Forecast keeps its differentiator tag; the set-aside side only shows when it exists (a forecast\n    // has no DNA set_aside chip to duplicate). Otherwise just the \"Not yet on SAM.gov\" tag.\n    var fpill=hasSet ? '<span class=\"setpill sd\">'+esc(setAsideLabel(o.set))+'</span>' : '';\n    return '<div class=\"pvsetwrap\">'+fpill+'<span class=\"foretag\">Not yet on SAM.gov</span></div>';\n  }\n  // OPEN: the set-aside is already the \"✓ <program> Set-Aside\" green DNA chip above (dnaChips), so the\n  // bottom pill would DUPLICATE it — and worse, it showed the BARE program name (\"Small Business\")\n  // under a chip that already said \"Small Business Set-Aside\" (Eric 2026-08-04). Suppress the pill when\n  // the genome carries the set_aside chip; keep it only as a FALLBACK if the chip is somehow absent, so\n  // the set-aside is never shown NOWHERE. Full-&-open opps → \"Open competition\" (stated by no chip).\n  if(hasSet){\n    var chipHasSetAside = Array.isArray(o.dna) && o.dna.some(function(s){return s && s.key==='set_aside';});\n    if(chipHasSetAside) return '';\n    return '<div class=\"pvsetwrap\"><span class=\"setpill sd\">'+esc(setAsideLabel(o.set))+'</span></div>';\n  }\n  return '<div class=\"pvsetwrap\"><span class=\"setpill\">Open competition</span></div>';\n}\n// The primary CTA text MATCHES the lifecycle (Eric 2026-08-04): Track Forecast · Review\n// Opportunity · Analyze Recompete. Never generic, never \"Should I bid?\".\nfunction lcCTA(o){\n  return o.src==='FORECAST'?'Track Forecast'\n    : o.src==='RECOMPETE'?'Analyze Recompete'\n    : 'Review Opportunity';\n}\n// The Expanded Decision Card (Eric 2026-08-04, frozen): the pin popup is a compressed decision\n// preview, NOT a mini-listing. Six slots, always in order:\n//   1 Lifecycle header (● label + quiet horizon line)  2 Identity (agency · story)\n//   3 Value hero (≈ ONLY on a modeled OPEN opp; recompete = real value, forecast = agency's own\n//     published range — both without ≈)                4 Title (2-line clamp)\n//   5 One context sentence + one set-aside/context chip 6 Lifecycle-matched CTA.\n// Everything heavier — the four-box grid, NAICS, response-due, solicitation #, \"View on SAM\" —\n// moved DOWN one level to the LISTING, because none of it changes the open-or-skip decision the\n// popup is for. Instrumented at the bindPopup seam: __trackCard('popup_open', …) on popupopen +\n// __trackCard('cta_click', …) delegated on .pv-cta — both carry lifecycle + identity metadata.\n// Location line under the popup title — parity with the card's .cmeta (Eric 2026-08-04 example shows\n// \"Lansing, MI\" under the title). Same grounding: an unplaced/forecast row shows its noLoc label with\n// an open ○ marker; a placed row shows its real place-of-performance. Renders nothing if we have neither.\n// Tidy a \"CITY, ST\" (or \"CITY, State Name\") label: Title-Case a SHOUTING city but leave a 2-letter\n// state CODE upper (\"FORT MCCOY, WI\" -> \"Fort McCoy, WI\"). Only touches all-caps input.\n// Title-Case one shouting token, with a fixup for Scottish/Irish \"Mc\"/\"Mac\" names so \"MCCOY\" ->\n// \"McCoy\" (not \"Mccoy\") — SAM place names hit this often (Fort McCoy, McConnell AFB, MacDill).\nfunction titleCaseWord(str){\n  // Process token-by-token off the ORIGINAL so we can KEEP short all-caps ACRONYMS uppercase\n  // (NBSFS, RFI, HVAC, FRC — Eric 2026-08-04: \"NBSFS\" must not become \"Nbsfs\"). A token is treated as\n  // an acronym when it was ALL-CAPS (letters only) and short/vowel-less enough to not be a real word:\n  // 2-5 letters with a digit-or-no-vowel shape, or any all-caps ≤4 letters. Everything else Title-Cases.\n  return String(str).replace(/[A-Za-z][A-Za-z&/'.-]*/g,function(w){\n    var letters=w.replace(/[^A-Za-z]/g,'');\n    var allCaps = letters.length>=2 && w===w.toUpperCase();\n    // An acronym stays uppercase only when it's ALL-CAPS and clearly NOT a normal word: vowel-less\n    // (NBSFS, GATK, FRC, RFQ, DLA), OR a 2-letter all-caps (FY, PO, IT). Common short words with a\n    // vowel (TANK, FORT, WATER, BASE) DO title-case. (Dictionary acronyms like HVAC/RFI are already\n    // handled by TITLE_ABBR upstream.)\n    var vowelless = !/[AEIOU]/.test(letters);\n    if(allCaps && (vowelless || letters.length===2)) return w;\n    var t=w.toLowerCase().replace(/^([a-z])/,function(m,c){return c.toUpperCase();});\n    t=t.replace(/^Mc([a-z])/,function(m,c){return 'Mc'+c.toUpperCase();});\n    t=t.replace(/^Mac([a-z])(?=[a-z]{2})/,function(m,c){return 'Mac'+c.toUpperCase();});\n    return t;\n  });\n}\nfunction tidyLoc(s){\n  var str=String(s==null?'':s).trim(); if(!str) return '';\n  var parts=str.split(',');\n  var head=parts[0].trim();\n  if(head===head.toUpperCase()) head=titleCaseWord(head);\n  var tail=parts.slice(1).join(',').trim();\n  if(tail){ if(/^[A-Za-z]{2}$/.test(tail)) tail=tail.toUpperCase();\n    else if(tail===tail.toUpperCase()) tail=titleCaseWord(tail); }\n  return tail?head+', '+tail:head;\n}\nfunction pvLoc(o){\n  var placed = o.loc && String(o.loc).trim();\n  var noloc = o.noLoc && String(o.noLoc).trim();\n  if(o.noPin){\n    var lbl = noloc || placed;\n    return lbl ? '<div class=\"pvloc noloc\">○ '+esc(tidyLoc(lbl))+'</div>' : '';\n  }\n  return placed ? '<div class=\"pvloc\">'+esc(tidyLoc(o.loc))+'</div>' : '';\n}\n// The urgency GREEN CHECK (Eric 2026-08-04 example: \"✓ Due in 3 Days\" as a third check, not a\n// separate date sentence). Grounded from daysOut(o); shown ONLY when genuinely actionable-soon\n// (≤7 days out, still open) so it's a real \"act now\" signal, not a date restated as a verb. OPEN\n// opps only — RECOMPETE/FORECAST measure a different horizon and keep their own timing line.\nfunction dueChip(o){\n  if(o.src==='RECOMPETE'||o.src==='FORECAST') return '';\n  var d=daysOut(o);\n  if(!isFinite(d)||d<0||d>7) return '';\n  var t = d===0 ? 'Due today' : d===1 ? 'Due in 1 day' : 'Due in '+d+' days';\n  return '<span class=\"fit\"><svg class=\"fitic\" viewBox=\"0 0 24 24\"><use href=\"#dna-check\"/></svg>'+t+'</span>';\n}\nfunction popupHTML(o){\n  const col=srcColor(o);\n  // The context sentence: for RECOMPETE/FORECAST it's their timing line (\"Incumbent expires\" /\n  // \"Planned for\") — kept. For OPEN it's Due/Posted, which now duplicates the lifecycle header +\n  // the \"✓ Due in N days\" whyChip (Eric 2026-08-04: that was the second \"Posted Jul 21\"), so the\n  // render below gates `sent` to recompete/forecast only. The helper still computes for all callers.\n  const sent=pvSentence(o);\n  // The CTA STAYS ON-MAP (flywheel: never leak to claude.ai) — it opens the in-app detail drawer,\n  // labeled by lifecycle (Track Forecast / Review Opportunity / Analyze Recompete). For an OPEN opp\n  // it also kicks the \"Should I bid?\" AI analysis, exactly as the prior \"Should I bid?\" button did;\n  // the only change is the LABEL now matches the lifecycle. The .pv-cta hook + data-nid drive the\n  // cta_click telemetry wired at the bindPopup seam. The heart (top-right) keeps 1-click Save.\n  const nid=String(o.nid||o.sol||'');\n  const cta=(o.src==='FORECAST'||o.src==='RECOMPETE')\n    ? `<button class=\"pva pri pv-cta\" data-nid=\"${nid}\" onclick=\"window.openOppDrawer&&openOppDrawer('${nid}')\">${lcCTA(o)} &rarr;</button>`\n    : `<button class=\"pva pri pv-cta\" data-nid=\"${nid}\" onclick=\"window.openOppDrawer&&openOppDrawer('${nid}');setTimeout(function(){window.runAI&&runAI('${nid}');},450)\">${lcCTA(o)} &rarr;</button>`;\n  return `<div class=\"pv\">${lcHeader(o)}<div class=\"pvstrip\" style=\"background:${col}\"></div><div class=\"pvbody\">\n    <button class=\"pv-heart\" data-nid=\"${nid}\" data-sol=\"${esc(o.sol||'')}\" onclick=\"toggleFav(this)\" title=\"Save to Favorites\" aria-label=\"Save to Favorites\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 21C5.6 16.5 3 12.9 3 9.1A5 5 0 0112 6a5 5 0 019 3.1c0 3.8-2.6 7.4-9 11.9z\"/></svg></button>\n    ${dnaRow(o)}\n    ${cardHero(o)}\n    <div class=\"pvt\">${esc(cleanTitle(o.title))}</div>\n    ${pvLoc(o)}\n    ${whyGroups(o)}\n    ${(o.src==='RECOMPETE'||o.src==='FORECAST')&&sent?`<div class=\"pvsent\">${sent}</div>`:''}\n    ${o.src==='FORECAST'?pvSetRow(o):''}\n    <div class=\"pvacts\">${cta}</div></div></div>`;\n}\n\n// ---------- listing card ----------\n// ---------- Opportunity DNA helpers (Eric 2026-08-03, tasks/EPIC-opportunity-dna.md) ----------\n// Minimal HTML-escape for the DNA text nodes (agency label, horizon date) — controlled server data,\n// but escaped for hygiene since these go into innerHTML template strings.\nfunction esc(s){return String(s==null?'':s).replace(/[&<>\"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c];});}\n// Lifecycle = the CATEGORY HEADER (like Zillow's status), not a badge. Open/Recompete/Forecast,\n// matching the pin color. The \"when\" restates the horizon date it already carries.\nfunction lcHeader(o){\n  // FORECAST horizon = the anticipated timing (rides o.cat as \"Forecast · Q2 FY2026\"); drop the\n  // \"Forecast\" prefix so the quiet line reads just \"Q2 FY2026\".\n  var _ft=String(o.cat||'').split('·').pop().trim();\n  // OPEN opps: the top line now carries URGENCY on the right — \"N DAYS LEFT\" (Eric 2026-08-04: \"put it\n  // on the same visual line as the identity — OPEN NOW ... 3 DAYS LEFT. Now the top tells me what it\n  // is, and how urgent it is\"). Grounded from daysOut, shown ONLY when genuinely soon (≤14d); it\n  // REPLACES the old floating \"3 days left\" pill under the estimate. RECOMPETE/FORECAST keep their\n  // Expires / Planned-for date (their headline timing). Never \"Posted\" — that's a lesser fact.\n  var _dOpen=daysOut(o), _urgent='';\n  if(o.src!=='RECOMPETE'&&o.src!=='FORECAST'&&isFinite(_dOpen)&&_dOpen>=0&&_dOpen<=14){\n    _urgent = _dOpen===0?'DUE TODAY':_dOpen===1?'1 DAY LEFT':_dOpen+' DAYS LEFT';\n  }\n  var kind = o.src==='RECOMPETE' ? {c:'recomp',t:'Recompete',when:o.exp?('Expires '+shortDate(o.exp)):''}\n    : (o.src==='FORECAST' ? {c:'fore',t:'Forecast',when:(_ft&&!/^forecast$/i.test(_ft))?_ft:''}\n      : {c:'open',t:'Open now',when:_urgent});\n  // urgent OPEN deadlines get the alert color (≤3d hot); the rest are quiet.\n  var whenCls = (kind.c==='open'&&_urgent) ? (_dOpen<=3?'lcwhen urg':'lcwhen soon') : 'lcwhen';\n  return '<div class=\"lchdr '+kind.c+'\"><span class=\"lcdot\"></span>'+kind.t\n    + (kind.when?'<span class=\"'+whenCls+'\">'+esc(kind.when)+'</span>':'') + '</div>';\n}\n// Identity + STORY on ONE line (Eric 2026-08-03: \"identity → story → estimate\", not\n// \"database → estimate → title\"). The agency SHORT CODE (Army/VA/GSA) is the recognizable brand\n// — one calm Landmark icon anchors it — followed by the buyer's STORY as \"· <story>\": the single\n// STRONGEST behavioral signal, never a pile (Eric: \"whichever is strongest\"). Priority: a repeat\n// buyer (o.repeat — prior awards in this NAICS; recompetes are repeat buys by definition) beats\n// SB-friendly (o.sbf — the buyer's measured PO-share top band). Each is real/grounded (set in\n// toRow) — never fabricated; when neither is true the line is just the identity.\n// Opportunity DNA — progressive reveal from the server-computed genome (o.dna). The genome is the\n// ONE source of truth (genome.ts); the client only PICKS how many strands a surface shows (Eric\n// 2026-08-04: \"make the existing vocabulary visible, consistent, and memorable\" — strict reveal:\n// card=1, popup=3, listing=all). dnaTop mirrors the server topStrands() sort: tier ascending (the\n// \"can I win?\" Tier-1 strands first), then a 'good' strand before a 'watch'/'neutral' one, so the\n// card leads with the strongest positive. Returns up to n strand LABELS. No genome → []. No new\n// strands are minted here — this is render-only.\n// Deliberate strand READ ORDER, shared by the identity line (dnaTop) and the Why chips (whyChips) so\n// they never disagree (Eric 2026-08-04): buyer trust first (repeat_buyer > sb_friendly), then the\n// opportunity's lifecycle/eligibility, then timing — a positive ('good') always before a 'watch'.\n// The identity line takes the TOP strand; whyChips takes the rest. This is why the identity line\n// leads with \"Repeat Buyer\" and the eligibility (\"HUBZone Set-Aside\") trails as a chip.\nfunction dnaOrder(dna){\n  var RANK = { repeat_buyer:0, sb_friendly:1, posts_early:2, sources_sought:3, early_cycle:4, recompete:5, forecast:6, set_aside:7, full_open:8, closes_soon:9, last_chance:10 };\n  var tone={good:0,watch:1,neutral:2};\n  return dna.slice().sort(function(a,b){\n    var ra=(a.key in RANK)?RANK[a.key]:50, rb=(b.key in RANK)?RANK[b.key]:50;\n    return (a.tier-b.tier) || (ra-rb) || ((tone[a.tone]||0)-(tone[b.tone]||0));\n  });\n}\nfunction dnaTop(dna,n){\n  if(!dna||!dna.length) return [];\n  return dnaOrder(dna).slice(0,n).map(function(s){return s.label;});\n}\n// cleanTitle() — the title reads like a deal, not a solicitation record (Eric 2026-08-04:\n// \"W911SA26RA026 REGION 3 JOC 5 YEAR — that's government language\"). DETERMINISTIC, no LLM, no\n// guessing (Eric's explicit choice — ground every fact, never an LLM guess): it only REFORMATS the\n// row's own title. Steps: (1) strip a leading solicitation number (the W911…/N001…/36C… PIID that\n// prefixes many titles); (2) expand a CURATED GovCon abbreviation dictionary (JOC -> Job Order\n// Contract, IDIQ, MATOC, SATOC, PWS, SOW, RFP, RFI, RFQ, IFB, BPA, IDV, O&M, R&M, POP, FY, ANG…) —\n// whole-word only; (3) tidy \"N YEAR(S)\" -> \"(N-Year)\"; (4) Title-Case an ALL-CAPS result (leave\n// mixed-case titles alone). Nothing is INVENTED — a term not in the dictionary passes through as-is,\n// so JOC becomes \"Job Order Contract\", never a guessed \"Construction\". Keep the dict conservative.\nvar TITLE_ABBR = {\n  JOC:'Job Order Contract', MATOC:'Multiple Award Task Order Contract', SATOC:'Single Award Task Order Contract',\n  IDIQ:'IDIQ', IDV:'IDV', BPA:'Blanket Purchase Agreement', BOA:'Basic Ordering Agreement',\n  PWS:'Performance Work Statement', SOW:'Statement of Work', SOO:'Statement of Objectives',\n  RFP:'RFP', RFI:'RFI', RFQ:'RFQ', IFB:'IFB', 'O&M':'Operations & Maintenance', 'R&M':'Repair & Maintenance',\n  POP:'Period of Performance', ANG:'Air National Guard', USACE:'Army Corps of Engineers',\n  HVAC:'HVAC', IT:'IT', NAICS:'NAICS', PSC:'PSC'\n};\nvar TITLE_STOP = { FOR:1, AND:1, OR:1, THE:1, OF:1, TO:1, A:1, AN:1, IN:1, ON:1, AT:1, BY:1, WITH:1 };\nfunction cleanTitle(t){\n  var s=String(t==null?'':t).trim();\n  if(!s) return '';\n  // 1. strip a leading solicitation/PIID token (e.g. \"W911SA26RA026 \") — a letter+digit code ≥8 chars.\n  s=s.replace(/^([A-Z0-9][A-Z0-9-]{6,}[0-9][A-Z0-9-]*)\\s+(?=\\S)/,'');\n  // 2. Title-Case a SHOUTING title (leave an already-mixed-case title alone). Do this BEFORE any other\n  // rewrite so nothing (a lowercase \"Year\", an expanded abbrev) poisons the all-caps check.\n  var shout = s===s.toUpperCase();\n  if(shout) s=titleCaseWord(s);\n  // 3. \"5 YEAR\"/\"5-YEAR\"/\"5 YR\" -> \"(5-Year)\".\n  s=s.replace(/\\b(\\d{1,2})[\\s-]*(?:year|yr)s?\\b/ig,'($1-Year)');\n  // 4. expand curated abbreviations — whole word, case-insensitive → each maps to its stored casing;\n  //    otherwise, on a title we just title-cased, lowercase the small stopwords (\"For\"->\"for\").\n  s=s.replace(/[A-Za-z][A-Za-z&/]*[A-Za-z]|[A-Za-z]/g,function(w){\n    var hit=TITLE_ABBR[w.toUpperCase()]; if(hit!=null) return hit;\n    if(shout && TITLE_STOP[w.toUpperCase()]) return w.toLowerCase();\n    return w;\n  });\n  return s.replace(/\\s+/g,' ').replace(/\\(\\s+/g,'(').replace(/\\s+\\)/g,')').trim();\n}\n// The identity line reads like Zillow, not a database dump (Eric 2026-08-04: \"DEPT OF THE ARMY —\n// that's database language. I'd rather see Army. Large. Clean.\"). shortAgency() turns a raw agency/\n// sub-agency string into the SHORTEST recognizable name — never fabricated, only a transform of the\n// row's own value: drop the inverted \", DEPARTMENT OF THE\" (SAM's \"ARMY, DEPARTMENT OF THE\"), strip a\n// leading \"U.S./UNITED STATES\" then \"DEPARTMENT/DEPT OF (THE)\", collapse whitespace, and Title-Case an\n// ALL-CAPS result. An already-clean label (\"Army\", \"Veterans Affairs\") passes through unchanged.\nfunction shortAgency(name){\n  var s=String(name==null?'':name).trim();\n  if(!s) return '';\n  s=s.replace(/,\\s*department\\s+of(\\s+the)?\\s*$/i,'');\n  s=s.replace(/^(the\\s+)?(u\\.?s\\.?|united\\s+states)\\s+/i,'');\n  s=s.replace(/^dep(artmen)?t\\.?\\s+of\\s+(the\\s+)?/i,'');\n  s=s.replace(/\\s+/g,' ').trim();\n  if(s===s.toUpperCase()) s=s.toLowerCase().replace(/\\b([a-z])/g,function(m,c){return c.toUpperCase();});\n  return s;\n}\nfunction dnaRow(o){\n  // Identity = SUB-agency (\"Army\"), NOT the parent dept; fall back to dept when subAgency is empty\n  // (~0.4% of pins). Both are clean()'d in toRow. (Eric 2026-08-03.)\n  var ag = (o.subAgency && String(o.subAgency).trim()) ? String(o.subAgency) : (o.agency ? String(o.agency) : '');\n  ag = shortAgency(ag); // \"DEPT OF THE ARMY\" -> \"Army\" (Eric 2026-08-04)\n  if(!ag) return '';\n  // STORY = the ONE dominant genome strand (strict reveal, card=1). Grounded, never fabricated —\n  // dnaTop returns [] when the opp has no strands, so the line is just the identity.\n  var top = dnaTop(o.dna,1);\n  var story = top.length ? top[0] : '';\n  var storyHTML = story ? '<span class=\"story\"><span class=\"middot\">·</span>'+esc(story)+'</span>' : '';\n  return '<div class=\"idrow\"><span class=\"agid\"><svg class=\"dnaic\" viewBox=\"0 0 24 24\"><use href=\"#dna-landmark\"/></svg>'+esc(ag)+'</span>'+storyHTML+'</div>';\n}\n// Popup DNA — THREE grounded strands (strict reveal, popup=3) as a chip row, from the same genome.\n// One green check per strand; renders nothing when the opp has no genome (never a fabricated chip).\nfunction dnaChips(o){\n  var top = dnaTop(o.dna,3);\n  var c = top.map(function(lbl){\n    return '<span class=\"fit\"><svg class=\"fitic\" viewBox=\"0 0 24 24\"><use href=\"#dna-check\"/></svg>'+esc(lbl)+'</span>';\n  }).join('');\n  c += dueChip(o); // \"Due in 3 Days\" rides the same green-check row (Eric 2026-08-04)\n  return c ? '<div class=\"fitrow\">'+c+'</div>' : '';\n}\n// \"Why this opportunity\" — the popup's chip row, DEDUPED (Eric 2026-08-04). Every duplicate the\n// screenshots showed is removed: the strand ALREADY on the identity line (dnaRow shows the top one,\n// e.g. \"· POSTS EARLY\") is dropped here; timing strands covered by the dueChip (closes_soon,\n// last_chance) are dropped (the \"Due in N days\" check says it better); and posts_early never rides\n// the chip row (it's an identity-line strand). What remains — the set-aside, repeat-buyer, sb-friendly,\n// early-cycle, etc. — renders as green checks under a subtle heading, followed by the dueChip. Empty →\n// nothing (no heading with no chips). Grounded: labels come straight from the server genome.\n// The grounded CONFIDENCE line under the ≈ estimate (Eric 2026-08-04: \"a single confidence line — not\n// AI, not a score — just 'Estimated from 217 similar awards'\"). o.estN is the REAL comparable-award\n// count behind the M-Estimate (parsed server-side from intel_value_range.label). Renders ONLY when we\n// have both a modeled estimate AND a real count — never a fabricated number; forecasts/recompetes\n// (whose value is the agency's own figure / the real contract, not a modeled band) get no line.\n// The grounded confidence line under the ≈ M-Estimate (Eric 2026-08-05: \"Likely $68.9M–$93.3M\n// underneath, tiny\"). Leads with the REAL low–high band (25th–75th pct of the comparable awards,\n// intel_value_range.low/high threaded onto the pin as estLow/estHigh) — \"Likely $Low–$High\". Falls\n// back to \"Estimated from N similar awards\" (the comparable count) when we have a count but no band.\n// Renders ONLY on a modeled OPEN estimate; never fabricated (no band + no count -> nothing);\n// recompete/forecast use a real/published value, so no modeled confidence line.\nfunction confLine(o){\n  if(o.src==='RECOMPETE'||o.src==='FORECAST') return '';\n  var est=Number(o.est||0); if(!(est>0)) return '';\n  var lo=Number(o.estLow||0), hi=Number(o.estHigh||0);\n  if(lo>0&&hi>0&&hi>=lo){\n    var loS=estMoney(lo), hiS=estMoney(hi);\n    if(loS&&hiS) return '<div class=\"conf\">Likely '+esc(loS)+'&ndash;'+esc(hiS)+'</div>';\n  }\n  var n=Number(o.estN||0);\n  if(n>0) return '<div class=\"conf\">Estimated from '+n.toLocaleString('en-US')+' similar awards</div>';\n  return '';\n}\n// \"Why this opportunity\" — the genome, GROUPED BY MEANING and DEDUPED (Eric 2026-08-04). Instead of one\n// flat check row, three quiet meaning-groups, each a micro-label + a row of pills (NO checkmarks — less\n// noise). Grounded: every pill is a real genome strand or the row's real set/deadline.\n//   • Opportunity — what kind of opening (sources_sought / recompete / forecast). DEDUP: sources_sought\n//     ABSORBS early_cycle (Eric: \"if it's Sources Sought it's almost always early — two slots, one\n//     signal\"), so early_cycle is dropped whenever sources_sought is present.\n//   • Eligibility — can you compete (the set-aside, or Open competition).\n//   • Timing — when to act (Due in N days), OPEN + genuinely-soon only.\n// Buyer signals (repeat_buyer / sb_friendly) stay on the identity line up top — never repeated here.\n// A group with no real signal is omitted (never a padded row); all-empty → nothing.\nfunction whyGroups(o){\n  var dna = Array.isArray(o.dna) ? o.dna : [];\n  var have = {}; dna.forEach(function(s){ if(s&&s.key) have[s.key]=s.label; });\n  var identityKey = (dnaOrder(dna)[0]||{}).key || '';   // the strand already on the identity line\n  function pill(lbl,cls){ return '<span class=\"wpill'+(cls?' '+cls:'')+'\">'+esc(lbl)+'</span>'; }\n  function group(label,html){ return html ? '<div class=\"wgrp\"><div class=\"wglabel\">'+label+'</div><div class=\"wprow\">'+html+'</div></div>' : ''; }\n\n  // Opportunity — dedup sources_sought vs early_cycle; skip whichever is the identity strand.\n  var opp='';\n  if(have.sources_sought && identityKey!=='sources_sought') opp+=pill(have.sources_sought);\n  else if(have.early_cycle && !have.sources_sought && identityKey!=='early_cycle') opp+=pill(have.early_cycle);\n  if(have.recompete && identityKey!=='recompete') opp+=pill(have.recompete);\n\n  // Eligibility — the real set-aside (named), else Open competition. Not on the identity line.\n  var elig='';\n  var hasSet=o.set && o.set!=='None' && o.set!=='NONE';\n  if(hasSet) elig=pill(setAsideLabel(o.set),'elig');\n  else if(have.full_open) elig=pill('Open competition','elig');\n\n  // Timing — the OPEN deadline moved UP to the header (\"N DAYS LEFT\", Eric 2026-08-04), so it's NO\n  // longer a group pill here (would double-show). Left intentionally empty for OPEN; the group is\n  // omitted. (Recompete/forecast timing lives in their own pvSentence line, not here.)\n  var body = group('Opportunity',opp) + group('Eligibility',elig);\n  if(!body) return '';\n  return '<div class=\"whyhdr\">Why this opportunity</div>'+body;\n}\n// Fit chips (the approved card artifact, Eric 2026-08-03): a row of GREEN check chips below the buyer\n// line — \"Fits your NAICS · Repeat buyer · SB-friendly\". Each renders ONLY when its real flag is\n// true (never fabricated): o.fits (card NAICS ∈ the signed-in user's profile codes, server-set on\n// the scope=profile path), o.repeat (this buyer has prior awards in this NAICS — recompete rows are\n// repeat buys by definition; open opps get it from the agency+NAICS award history), o.sbf (buyer's\n// measured PO-share top band). No chip is shown for a signal we can't ground → the row can be empty.\nfunction fitChips(o){\n  var c='';\n  if(o.fits)   c+='<span class=\"fit\"><svg class=\"fitic\" viewBox=\"0 0 24 24\"><use href=\"#dna-check\"/></svg>Fits your NAICS</span>';\n  if(o.repeat) c+='<span class=\"fit\"><svg class=\"fitic\" viewBox=\"0 0 24 24\"><use href=\"#dna-check\"/></svg>Repeat buyer</span>';\n  if(o.sbf)    c+='<span class=\"fit\"><svg class=\"fitic\" viewBox=\"0 0 24 24\"><use href=\"#dna-check\"/></svg>SB-friendly</span>';\n  return c?'<div class=\"fitrow\">'+c+'</div>':'';\n}\nfunction cardHTML(o){\n  const d=daysOut(o),f=fmtDays(d,o.src==='RECOMPETE'),col=srcColor(o);\n  const agency=AGENCY[o.agency]||o.agency;\n  const stats=o.src==='RECOMPETE'\n   ?`<div class=\"st\"><div class=\"k\">Contract value</div><div class=\"v money\">${(Number(o.valueNum)>0?estMoneyExact(o.valueNum):(o.value||'—'))}</div></div>\n     <div class=\"st\"><div class=\"k\">Win odds</div><div class=\"v ${o.prob==='high'?'hi':'med'}\">${(o.prob||'—').replace(/^./,c=>c.toUpperCase())}</div></div>\n     <div class=\"st\"><div class=\"k\">Expires</div><div class=\"v\">${shortDate(o.exp)}</div></div>`\n   :`<div class=\"st\"><div class=\"k\">Set-aside</div><div class=\"v ${o.set==='SDVOSB'?'sd':''}\">${o.set==='None'?'Open':o.set}</div></div>\n     <div class=\"st\"><div class=\"k\">NAICS</div><div class=\"v\">${o.naics}</div></div>\n     <div class=\"st\"><div class=\"k\">Due</div><div class=\"v\">${shortDate(o.close)}</div></div>`;\n  // The status pill only earns its place when the TIMING is genuinely actionable — otherwise it\n  // just restates the Due/Expires date cell (Eric 2026-07-27: \"same info said differently, no\n  // value\"; and \"Recompete now on every card is not how Zillow does it\" — Zillow shows the sold\n  // date, not a verb stamped on every card). Show it ONLY when it adds a decision the date can't:\n  //  - OPEN, genuinely urgent (f.c==='hot' → ≤3 days / due today) — a scannable \"act now\" flag; OR\n  //  - a RECOMPETE in its ACTIONABLE window (f.c==='warm' → \"Expiring now\"/\"Expiring soon\") —\n  //    the rebid is live/near, a strategic cue the Expires date alone doesn't convey.\n  // The \"Active — subcontract\" majority (f.c==='cool') drops the pill; the Expires cell carries it.\n  // The floating \"N days left\" urgency pill is GONE for OPEN opps — it moved UP to the header's right\n  // side (\"OPEN NOW … 3 DAYS LEFT\", Eric 2026-08-04). Only a RECOMPETE in its actionable window still\n  // gets the slim pill here (its urgency isn't in the OPEN-only header line).\n  const showDl = (o.src==='RECOMPETE' && f.c==='warm');\n  // DNA order (Eric 2026-08-03, \"identity → story → estimate\", NOT \"database → estimate → title\"):\n  //   lifecycle header (OPEN NOW) → IDENTITY+STORY line (Army · Repeat Buyer) → estimate hero\n  //   (≈ $8.2M — no longer carrying identity) → title → location → facts (set-aside · due).\n  // Docs chip REMOVED (Eric: \"Docs doesn't belong on the card\"). The fit-chip row is GONE too —\n  // its Repeat/SB story moved UP onto the identity line (dnaRow), so a chip row below would just\n  // repeat it. earlySignal + genuine-urgency pills still ride a slim row under the estimate.\n  const crow = earlySignalChip(o) + (showDl?`<span class=\"dl ${f.c}\"><i></i>${f.t}</span>`:'');\n  return `${lcHeader(o)}<div class=\"cstrip\" style=\"background:${col}\"></div><div class=\"cbody\">\n    ${dnaRow(o)}\n    ${cardHero(o)}\n    ${crow?`<div class=\"crow1\">${crow}</div>`:''}\n    <div class=\"ctitle\">${esc(cleanTitle(o.title))}</div>\n    <div class=\"cmeta\">${o.src==='RECOMPETE'&&o.cat?'<span class=\"ind\">'+o.cat+'</span><span class=\"dot\"></span>':''}${o.noPin?('<span class=\"loc noloc\">○ '+(o.noLoc||o.loc)+'</span>'):('<span class=\"loc\">'+o.loc+'</span>')}</div>\n    <div class=\"stats\">${stats}</div>\n    <div class=\"cfoot\">\n      <span class=\"solno\">${o.noPin?'Forecast — not yet on SAM':o.sol}</span>\n      <a class=\"act\" href=\"${samURL(o)}\" target=\"_blank\" rel=\"noopener\" onclick=\"event.stopPropagation()\">SAM.gov</a>\n      <a class=\"act pri\" href=\"${draftURL(o)}\" target=\"_blank\" rel=\"noopener\" onclick=\"event.stopPropagation()\">${draftCTA(o)}</a>\n    </div></div>`;\n}\n\n// ---------- filtering + render ----------\nfunction pass(o){\n  if(!F.src.has(o.src))return false;\n  if(!F.cat.has(o.cat))return false;\n  if(!F.set.has(setKey(o.set)))return false;\n  if(F.sdOnly&&setKey(o.set)!=='SDVOSB')return false;\n  if(F.soon){const d=daysOut(o);if(d<0||d>7)return false;}\n  return true;\n}\n// \"Recommended\" for OPEN opportunities — the Zillow-relevance blend (Eric 2026-07-28: the default was\n// just \"soonest deadline\", one dimension wearing the Recommended label — same gap the Companies sort\n// had). A transparent blend of REAL opp fields, NONE fabricated, higher = more recommended:\n//   • urgency — an opp closing in the actionable window (days-out) is timely, but past its window it\n//     DROPS (a due-tomorrow opp you can't realistically bid isn't \"recommended\"); ~2-8 weeks out peaks.\n//   • freshness — a recently POSTED opp beats a stale one (more likely still real + full runway).\n//   • set-aside relevance — an opp with a set-aside a small biz can pursue gets a boost.\n//   • value — the M-Estimate (o.est), LOG-scaled so a big opp counts without swamping a fitting small one.\n//   • docs — a real pulled solicitation package (o.docs) is more biddable than a bare notice.\n// All terms ~0..1, weighted. RECOMPETE rows are NOT scored here (different semantics — they keep the\n// deadline order); this only re-ranks the Open/SAM default view.\nfunction oppRecommendedScore(o){\n  var d=daysOut(o); // days until the response deadline (NaN if none)\n  // Urgency: peaks in the 3–45 day pursue window; a past/at-0 deadline or a far-off one scores lower.\n  var urgency;\n  if(!isFinite(d)) urgency=0.3;                       // no deadline → neutral-low\n  else if(d<0) urgency=0.05;                          // already closed → almost out\n  else if(d<=3) urgency=0.55;                         // very soon — urgent but hard to start\n  else if(d<=45) urgency=1;                           // the sweet spot — time to actually bid\n  else if(d<=90) urgency=0.7;\n  else urgency=0.45;                                  // far out — real but not pressing\n  // Freshness: posted within ~7 days = full credit, decaying to ~0 by 60 days old.\n  var pd=String(o.posted||'').slice(0,10);\n  var ageDays=pd?Math.max(0,Math.round((TODAY-new Date(pd+'T12:00:00'))/864e5)):45;\n  var freshness=Math.max(0,1-ageDays/60);\n  // Set-aside relevance: a real set-aside (not \"None\") a small business can pursue.\n  var setAside=(o.set&&o.set!=='None'&&o.set!=='Open')?1:0;\n  // Value: log-scaled M-Estimate median (o.est), ~$10K→0 .. ~$100M→1. No estimate → 0 (never fabricated).\n  var v=Number(o.est)||0;\n  var valTerm=v>0?Math.min(1,Math.max(0,(Math.log10(v)-4)/5)):0;\n  var docs=o.docs?1:0;\n  return 0.40*urgency + 0.24*freshness + 0.16*setAside + 0.12*valTerm + 0.08*docs;\n}\n// \"Recommended\" for RECOMPETES — the relevance blend (Eric 2026-07-28: the default was just \"soonest\n// expiration\", one dimension). A recompete is a rebid/subcontract target; the blend surfaces the ones\n// worth CHASING, all from real row fields (win-probability isn't threaded to the map pin, so it's a\n// queued fast-follow — NOT fabricated here):\n//   • window timing — the ACTIONABLE recompete window is ~6–18 months before expiry (agencies post\n//     the follow-on 6–18mo out). An expiry in that window peaks; already-expired or far-off scores low.\n//   • contract-type actionability — a TASK ORDER / DELIVERY ORDER (a small firm can sub it NOW) or a\n//     small-buy (BPA call / purchase order) outranks a giant parent IDIQ vehicle.\n//   • set-aside relevance — a set-aside the small biz can pursue.\n//   • value — log-scaled contract ceiling (valueNum); bigger recompete counts, doesn't swamp fit.\nfunction recompeteRecommendedScore(o){\n  // Months until expiration (exp is YYYY-MM-DD). daysOut(o) already measures against o.exp for RECOMPETE.\n  var d=daysOut(o); var months=isFinite(d)?d/30.44:NaN;\n  var timing;\n  if(!isFinite(months)) timing=0.3;\n  else if(months<0) timing=0.1;                 // already expired — follow-on likely already out/gone\n  else if(months<=6) timing=0.75;               // very near — solicitation likely already posted\n  else if(months<=18) timing=1;                 // THE window — get ahead of the rebid\n  else if(months<=30) timing=0.6;\n  else timing=0.4;                              // far out — worth tracking, not pressing\n  // Contract-type actionability from the awardTypeBadge language (task/delivery order, small buys).\n  var ct=String(o.contractType||'').toUpperCase();\n  var actionable=(ct.indexOf('TASK ORDER')>=0||ct.indexOf('DELIVERY ORDER')>=0||ct.indexOf('BPA')>=0||ct.indexOf('PURCHASE ORDER')>=0)?1\n    :(ct.indexOf('DEFINITIVE')>=0?0.6:0.35);    // a bare parent IDIQ vehicle is the least directly-actionable\n  var setAside=(o.set&&o.set!=='None'&&o.set!=='Open')?1:0;\n  var v=Number(o.valueNum)||0;\n  var valTerm=v>0?Math.min(1,Math.max(0,(Math.log10(v)-4)/5)):0;\n  var s=0.42*timing + 0.24*actionable + 0.18*setAside + 0.16*valTerm;\n  // Hard floor for an ALREADY-EXPIRED recompete: you can't chase a rebid that's gone, so it must never\n  // outrank a live one no matter how attractive its size/set-aside/type (Eric 2026-07-28). Halve it so\n  // it always sits below any live recompete — timing as a gate, not just a weighted term.\n  if(isFinite(months)&&months<0) s*=0.5;\n  return s;\n}\nfunction sortRows(a,b){\n  switch(F.sort){\n    case 'deadline-far':return dueDate(b).localeCompare(dueDate(a));\n    case 'value':return valNum(b)-valNum(a);\n    case 'az':return a.title.localeCompare(b.title);\n    default:{\n      // \"Recommended\" (empty F.sort) — each dataset uses its OWN relevance blend (Eric 2026-07-28,\n      // \"fix Recommended for all 4 categories\"). OPEN/SAM opps → oppRecommendedScore; RECOMPETE →\n      // recompeteRecommendedScore. Both rows must be the SAME kind to compare scores; otherwise\n      // (mixed, shouldn't happen in one dataset view) fall back to the deadline order.\n      var ar=(a.src==='RECOMPETE'), br=(b.src==='RECOMPETE');\n      if(ar&&br){ var ra=recompeteRecommendedScore(a), rb=recompeteRecommendedScore(b); if(rb!==ra)return rb-ra; return dueDate(a).localeCompare(dueDate(b)); }\n      if(!ar&&!br){ var sa=oppRecommendedScore(a), sb=oppRecommendedScore(b); if(sb!==sa)return sb-sa; return dueDate(a).localeCompare(dueDate(b)); }\n      return dueDate(a).localeCompare(dueDate(b));\n    }\n  }\n}\nfunction render(){\n  refreshFacets(); // union any newly-loaded horizon's src/cat into the (selected) filter sets first\n  rows=OPPS.filter(pass).sort(sortRows);\n  // map\n  layer.clearLayers();markers.clear();\n  var _zFar=(typeof pinTooFar==='function')&&pinTooFar(map);\n  var _zh=document.getElementById('zoomHint'); if(_zh)_zh.hidden=!_zFar;\n  // Zillow: country zoom has no pins (\"Zoom in to see opportunities\"). Regional = dots;\n  // close-in = $-value tags (pinFace). Skip the pin loop when too far out — the list still fills.\n  if(!_zFar){\n  const _cl=(typeof clusterRows==='function')?clusterRows(rows,map,64):{singles:rows,clusters:[]};\n  _cl.clusters.forEach(cl=>{\n    const cb=mkClusterBubble(cl,map,'opps');cb.addTo(layer);\n  });\n  _cl.singles.forEach(o=>{\n    if(o.lat==null||o.lng==null)return; // list-only rows (unplaced forecasts) have no pin\n    const col=srcColor(o);\n    // Zillow value-tag pin: the $ on the pin IS the pin (M-Estimate median for Open, contract\n    // value for Awarded). No value → a small neutral dot (never a fabricated price). Overlap is\n    // allowed on purpose. mkPin/pinMoney are hoisted globals from PIN_JS.\n    const _txt=(typeof pinFace==='function')?pinFace(o,map):((typeof pinMoney==='function')?pinMoney(o):'');\n    const _approx=(o.locSrc==='office');\n    const m=(typeof mkPin==='function')\n      ? mkPin(o,col,_txt,_approx).bindPopup(popupHTML(o),{maxWidth:300,closeButton:true})\n      : L.circleMarker([o.lat,o.lng],{radius:6,color:'#ffffff',weight:2,fillColor:col,fillOpacity:.95}).bindPopup(popupHTML(o),{maxWidth:300,closeButton:true});\n    m.on('click',()=>{\n      // FUNNEL: pin_clicked — the second funnel step (map_open→pin_clicked→popup_open→…). Distinct\n      // from popup_open: a pin click that fails to open a popup shows as pin_clicked WITHOUT a\n      // following popup_open — a real drop-off signal. Fired via the shared __track pipe (signed-in\n      // only, fire-and-forget); tracking never blocks the select/popup. src in metadata for lifecycle.\n      try{ if(window.__track) window.__track('tool_use','pin_clicked',{notice_id:String(o.sol||o.nid||''),src:(o&&o.src)||''}); }catch(e){}\n      select(o.sol,false);\n    });\n    m.on('mouseover',()=>highlight(o.sol,true));\n    m.on('mouseout',()=>highlight(o.sol,false));\n    // Decision-card telemetry (Eric 2026-08-04): the popup OPEN + its CTA CLICK, both via the shared\n    // __trackCard pipe (signed-in only, fire-and-forget). popup_open answers \"which popup opens\" +\n    // carries lifecycle/identity; cta_click (delegated on .pv-cta so it survives the popup re-render)\n    // answers \"which CTA clicks / which lifecycle converts\". A tracking miss never blocks the popup.\n    m.on('popupopen',function(ev){\n      try{ if(window.__trackCard) window.__trackCard('popup_open', o.sol||o.nid, o);\n        var el=ev&&ev.popup&&ev.popup.getElement&&ev.popup.getElement();\n        var cta=el&&el.querySelector&&el.querySelector('.pv-cta');\n        if(cta&&!cta.__wired){ cta.__wired=1; cta.addEventListener('click',function(){\n          try{ if(window.__trackCard) window.__trackCard('cta_click', o.sol||o.nid, o); }catch(e){} }); }\n      }catch(e){}\n    });\n    m.addTo(layer);markers.set(o.sol,m);\n  });\n  }\n  // counts on filter buttons\n  document.getElementById('c-src').textContent=F.src.size===3?'':F.src.size;\n  document.getElementById('c-cat').textContent=F.cat.size===CATS.length?'':F.cat.size;\n  document.getElementById('c-set').textContent=F.set.size===SETGROUPS.length?'':F.set.size;\n  document.querySelectorAll('.fbtn[data-sheet]').forEach(b=>{\n    const k=b.dataset.sheet,full=k==='src'?3:k==='cat'?CATS.length:SETGROUPS.length;\n    b.classList.toggle('active',F[k].size!==full&&F[k].size>0);\n  });\n  // summary — NO subtitle line (Eric struck it through in red, Jul 26: \"23 SDVOSB-eligible · N\n  // closing this week\" is clutter). The clean count lives on the sort row (\"N results\"), set by\n  // updateHeader() in the viewport JS. This template render() path re-ran AFTER updateHeader cleared\n  // it and re-populated the killed line (Eric 2026-07-28: \"you snuck in the 23 sdvosb language\").\n  // Keep the sumline BLANK here so both paths agree. Do NOT reintroduce the SDVOSB/closing subtitle.\n  const sumEl=document.getElementById('sumline'); if(sumEl)sumEl.innerHTML='';\n  document.getElementById('rescount').innerHTML=\n    `<span style=\"font-weight:700;color:var(--ink)\">${rows.length}</span> <span style=\"font-weight:400;color:var(--sub)\">result${rows.length===1?'':'s'}</span>`;\n  // Then let the LIVE header win if it is present. updateHeader() (VIEWPORT_JS) knows TOTAL/CAPPED\n  // and renders Zillow's \"N of M results\" when we plot fewer than match; this template path only\n  // knows rows.length, so on the live page it would clobber that fraction with a bare count —\n  // whichever ran last used to win, which is exactly how these two paths drifted before. It\n  // early-returns when no data has loaded, so the line above stays as the standalone fallback.\n  if(typeof updateHeader==='function'){ try{ updateHeader(); }catch(e){} }\n  drawFeed();\n}\nfunction drawFeed(){\n  const feed=document.getElementById('feed');\n  if(!rows.length){\n    feed.innerHTML=`<div class=\"empty\"><h4>No opportunities match</h4>\n      <p>Try removing a filter or widening your service lines.</p>\n      <button onclick=\"document.getElementById('clrAll').click()\">Clear all filters</button></div>`;\n    return;\n  }\n  feed.innerHTML='';\n  rows.forEach(o=>{\n    const c=document.createElement('article');\n    c.className='card';c.dataset.sol=o.sol;c.tabIndex=0;\n    c.innerHTML=cardHTML(o);\n    c.onclick=()=>select(o.sol,true);\n    c.onkeydown=e=>{if(e.key==='Enter')select(o.sol,true);};\n    c.onmouseenter=()=>highlight(o.sol,true,true);\n    c.onmouseleave=()=>highlight(o.sol,false,true);\n    feed.appendChild(c);\n  });\n}\n// Fetch-failure banner — a FAILED viewport fetch (network blip / mid-deploy chunk mismatch) must\n// NOT read as a genuine \"No opportunities match\". _showFetchError paints an honest retry state and\n// leaves any already-rendered cards in place; _clearFetchError removes it on the next good fetch.\n// (The live viewport JS in route.ts calls these when every enabled horizon's fetch failed.)\nfunction _showFetchError(){\n  var feed=document.getElementById('feed'); if(!feed)return;\n  if(document.getElementById('fetchErr'))return; // already shown — don't stack\n  var b=document.createElement('div'); b.id='fetchErr'; b.className='empty';\n  b.innerHTML='<h4>Couldn’t load this view</h4>'\n    +'<p>The map hit a network hiccup. Your results are still here — try again.</p>'\n    +'<button onclick=\"if(window.__mapRefetch)window.__mapRefetch()\">Retry</button>';\n  feed.insertBefore(b, feed.firstChild);\n}\nfunction _clearFetchError(){ var e=document.getElementById('fetchErr'); if(e)e.remove(); }\n// list <-> map sync\nfunction highlight(sol,on,fromCard){\n  const m=markers.get(sol);\n  if(m&&fromCard&&m.setStyle){\n    const rec=m.options.fillOpacity<.8;\n    m.setStyle({radius:on?(rec?11:9.5):(rec?7.5:6),weight:on?3:2});\n    if(on&&m.bringToFront){try{m.bringToFront();}catch(e){}} // clustered marker may not be on the map\n  }\n  if(!fromCard){\n    const c=document.querySelector(`.card[data-sol=\"${CSS.escape(sol)}\"]`);\n    if(c)c.classList.toggle('hot-hover',on);\n  }\n}\nfunction select(sol,fly){\n  selected=sol;\n  document.querySelectorAll('.card').forEach(c=>c.classList.toggle('sel',c.dataset.sol===sol));\n  const m=markers.get(sol);\n  if(m){\n    if(fly)map.flyTo(m.getLatLng(),Math.max(map.getZoom(),7),{duration:.6});\n    m.openPopup();\n  }\n  const c=document.querySelector(`.card[data-sol=\"${CSS.escape(sol)}\"]`);\n  if(c&&!fly)c.scrollIntoView({block:'nearest'});\n}\n\n// ---------- sidebar collapse ----------\nconst appEl=document.querySelector('.app'),railBtn=document.getElementById('railBtn');\nrailBtn.onclick=()=>{\n  const hid=appEl.classList.toggle('collapsed');\n  railBtn.classList.toggle('collapsed',hid);\n  railBtn.textContent=hid?'›':'‹';\n  railBtn.title=railBtn.ariaLabel=hid?'Show list':'Hide list';\n  // let the grid transition finish, then re-measure the map\n  [80,180,300,420].forEach(t=>setTimeout(resize,t));\n};\n\n// ---------- progress ----------\nconst LEVELS=[[\"Emerging\",0],[\"Active Bidder\",250],[\"Contender\",750],[\"Prime Ready\",2000],[\"Award Winner\",5000]];\nlet PROG={pts:0,week:0,streak:0,best:0,goal:500};\nconst sb=document.getElementById('sb');\nbindEl('sbOpen','onclick',()=>{if(sb)sb.classList.add('open');});\nbindEl('sbClose','onclick',()=>{if(sb)sb.classList.remove('open');});\nfunction paintScore(){\n  let i=0;for(let k=0;k<LEVELS.length;k++)if(PROG.pts>=LEVELS[k][1])i=k;\n  const cur=LEVELS[i],nxt=LEVELS[Math.min(i+1,LEVELS.length-1)];\n  document.getElementById('lvlName').textContent=cur[0].toUpperCase();\n  document.getElementById('ptsVal').textContent=PROG.pts;\n  document.getElementById('ptsMini').textContent=PROG.pts;\n  document.getElementById('nextName').textContent=i<LEVELS.length-1?`Next: ${nxt[0]}`:'Max level';\n  document.getElementById('nextGap').textContent=i<LEVELS.length-1?`${Math.max(0,nxt[1]-PROG.pts)} to go`:'—';\n  document.getElementById('lvlFill').style.width=Math.min(100,((PROG.pts-cur[1])/((nxt[1]-cur[1])||1))*100)+'%';\n  document.getElementById('weekPts').textContent=PROG.week;\n  document.getElementById('goalTxt').textContent=`${PROG.week}/${PROG.goal}`;\n  document.getElementById('streak').textContent=`${PROG.streak}`;\n  document.getElementById('best').textContent=PROG.best;\n}\ndocument.querySelectorAll('.lact').forEach(a=>{\n  a.onclick=()=>{const p=+a.dataset.p;PROG.pts+=p;PROG.week+=p;\n    if(PROG.week>PROG.best)PROG.best=PROG.week;if(!PROG.streak)PROG.streak=1;paintScore();};\n});\nbindEl('resetProg','onclick',()=>{PROG={pts:0,week:0,streak:0,best:0,goal:500};paintScore();});\n\ndocument.addEventListener('click',e=>{\n  if(openSheet&&!e.target.closest('.fbar'))closeSheet();\n});\n\nrender();paintScore();fitView();\n</script>\n</body>\n</html>\n";
